"use client";

import { useState } from "react";
import {
  Users,
  Plus,
  Search,
  Power,
  Edit,
  Shield,
  Mail,
  Phone,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { usePaginatedUsers, useRequests } from "@/hooks/use-api-data";
import { agentsApi } from "@/lib/api";
import { toast } from "sonner";

interface AgentForm {
  nom: string;
  prenoms: string;
  email: string;
  telephone: string;
  password: string;
  role: string;
  droits: {
    gererClients: boolean;
    gererEmissions: boolean;
    gererRequetes: boolean;
    exportDonnees: boolean;
  };
}

const emptyForm: AgentForm = {
  nom: "",
  prenoms: "",
  email: "",
  telephone: "",
  password: "",
  role: "agent",
  droits: {
    gererClients: true,
    gererEmissions: true,
    gererRequetes: true,
    exportDonnees: false,
  },
};

export default function AdminAgentsPage() {
  const PAGE_SIZE = 12;
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);

  const { data: paginatedAgents, loading, error, refetch: refetchUsers } = usePaginatedUsers({
    role: "agent",
    search: search.trim() || undefined,
    page,
    pageSize: PAGE_SIZE,
  });
  const { data: allRequests } = useRequests();
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [selectedAgent, setSelectedAgent] = useState<any>(null);
  const [form, setForm] = useState<AgentForm>({ ...emptyForm });

  const agents = paginatedAgents.results ?? [];
  const totalCount = paginatedAgents.count ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));

  const canGoPrev = page > 1;
  const canGoNext = page < totalPages;

  const handlePrev = () => {
    if (canGoPrev) setPage((p) => Math.max(1, p - 1));
  };

  const handleNext = () => {
    if (canGoNext) setPage((p) => p + 1);
  };

  const handleSearchChange = (value: string) => {
    setSearch(value);
    setPage(1);
  };

  const handleCreate = async () => {
    if (!form.nom || !form.prenoms || !form.email || !form.password) {
      toast.error("Veuillez remplir tous les champs obligatoires");
      return;
    }
    if (form.password.length < 8) {
      toast.error("Le mot de passe doit contenir au moins 8 caractères");
      return;
    }
    try {
      // Créer l'objet de données sans le téléphone si vide
      const createData: any = {
        nom: form.nom,
        prenoms: form.prenoms,
        email: form.email,
        password: form.password,
      };

      // Ajouter le téléphone seulement s'il n'est pas vide
      if (form.telephone && form.telephone.trim() !== "") {
        createData.telephone = form.telephone;
      }

      await agentsApi.create(createData);
      toast.success(`Agent ${form.nom} ${form.prenoms} créé avec succès.`);
      setShowAddDialog(false);
      setForm({ ...emptyForm });
      refetchUsers();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors de la création");
    }
  };

  const handleEdit = (agent: any) => {
    setSelectedAgent(agent);
    setForm({
      nom: agent.nom,
      prenoms: agent.prenoms,
      email: agent.email,
      telephone: agent.telephone,
      password: "", // Empty for edit (user can change if needed)
      role: agent.role,
      droits: {
        gererClients: true,
        gererEmissions: true,
        gererRequetes: true,
        exportDonnees: false,
      },
    });
    setShowEditDialog(true);
  };

  const handleUpdate = async () => {
    if (!selectedAgent || !form.nom || !form.prenoms || !form.email) {
      toast.error("Veuillez remplir tous les champs obligatoires");
      return;
    }

    // Skip password validation for inactive agents
    if (selectedAgent.is_active && form.password && form.password.length < 8) {
      toast.error("Le mot de passe doit contenir au moins 8 caractères");
      return;
    }

    try {
      const updateData: any = {
        nom: form.nom,
        prenoms: form.prenoms,
        email: form.email,
        telephone: form.telephone,
      };

      // Only include password if it's provided AND agent is active
      if (selectedAgent.is_active && form.password) {
        updateData.password = form.password;
      }

      await agentsApi.update(Number(selectedAgent.id), updateData);
      toast.success(`Agent ${form.nom} ${form.prenoms} mis à jour avec succès.`);
      setShowEditDialog(false);
      setSelectedAgent(null);
      setForm({ ...emptyForm });
      refetchUsers();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors de la mise à jour");
    }
  };

  const handleToggle = async (agent: any) => {
    try {
      const newStatus = !agent.is_active;
      await agentsApi.update(Number(agent.id), {
        nom: agent.nom,
        prenoms: agent.prenoms,
        email: agent.email,
        telephone: agent.telephone,
        is_active: newStatus,
      });

      const action = newStatus ? "activé" : "désactivé";
      toast.success(`Agent ${agent.nom} ${agent.prenoms} ${action}`);
      refetchUsers();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors de la modification");
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Users className="h-6 w-6" />
            Gestion des Agents
          </h1>
          <p className="text-gray-500 mt-1">
            Créez, modifiez et gérez les accès des agents ACS
          </p>
        </div>
        <div className="flex gap-3">
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Rechercher un agent..."
              value={search}
              onChange={(e) => handleSearchChange(e.target.value)}
              className="pl-9"
            />
          </div>
          <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
            <DialogTrigger asChild>
              <Button className="bg-[hsl(222,47%,20%)] hover:bg-[hsl(222,47%,25%)]">
                <Plus className="h-4 w-4 mr-1" /> Nouvel agent
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-md">
              <DialogHeader>
                <DialogTitle>Créer un agent</DialogTitle>
                <DialogDescription>
                  Remplissez les informations pour créer un nouvel agent.
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-4 pt-2">
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1.5">
                    <Label>Nom *</Label>
                    <Input
                      value={form.nom}
                      onChange={(e) => setForm({ ...form, nom: e.target.value })}
                      placeholder="Nom"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label>Prénoms *</Label>
                    <Input
                      value={form.prenoms}
                      onChange={(e) => setForm({ ...form, prenoms: e.target.value })}
                      placeholder="Prénoms"
                    />
                  </div>
                </div>
                <div className="space-y-1.5">
                  <Label>Email *</Label>
                  <Input
                    type="email"
                    value={form.email}
                    onChange={(e) => setForm({ ...form, email: e.target.value })}
                    placeholder="agent@acs.ci"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label>Téléphone</Label>
                  <Input
                    value={form.telephone}
                    onChange={(e) => setForm({ ...form, telephone: e.target.value })}
                    placeholder="+225 XX XX XX XX XX"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label>Mot de passe *</Label>
                  <Input
                    type="password"
                    value={form.password}
                    onChange={(e) => setForm({ ...form, password: e.target.value })}
                    placeholder="Minimum 8 caractères"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label>Rôle</Label>
                  <Select
                    value={form.role}
                    onValueChange={(v) => setForm({ ...form, role: v })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="agent">Agent</SelectItem>
                      <SelectItem value="admin">Administrateur</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label>Droits d&apos;accès</Label>
                  <div className="space-y-2 bg-gray-50 p-3 rounded-lg">
                    <label className="flex items-center gap-2 cursor-pointer">
                      <Checkbox
                        checked={form.droits.gererClients}
                        onCheckedChange={(c) =>
                          setForm({
                            ...form,
                            droits: { ...form.droits, gererClients: !!c },
                          })
                        }
                      />
                      <span className="text-sm">Gérer les clients</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <Checkbox
                        checked={form.droits.gererEmissions}
                        onCheckedChange={(c) =>
                          setForm({
                            ...form,
                            droits: { ...form.droits, gererEmissions: !!c },
                          })
                        }
                      />
                      <span className="text-sm">Gérer les émissions</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <Checkbox
                        checked={form.droits.gererRequetes}
                        onCheckedChange={(c) =>
                          setForm({
                            ...form,
                            droits: { ...form.droits, gererRequetes: !!c },
                          })
                        }
                      />
                      <span className="text-sm">Gérer les requêtes</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <Checkbox
                        checked={form.droits.exportDonnees}
                        onCheckedChange={(c) =>
                          setForm({
                            ...form,
                            droits: { ...form.droits, exportDonnees: !!c },
                          })
                        }
                      />
                      <span className="text-sm">Exporter les données</span>
                    </label>
                  </div>
                </div>

                <Button
                  className="w-full bg-[hsl(222,47%,20%)] hover:bg-[hsl(222,47%,25%)]"
                  onClick={handleCreate}
                >
                  Créer l&apos;agent
                </Button>
              </div>
            </DialogContent>
          </Dialog>

          {/* Edit Dialog */}
          <Dialog open={showEditDialog} onOpenChange={setShowEditDialog}>
            <DialogContent className="max-w-md">
              <DialogHeader>
                <DialogTitle>Modifier un agent</DialogTitle>
                <DialogDescription>
                  Modifiez les informations de l'agent sélectionné.
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-4 pt-2">
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1.5">
                    <Label>Nom *</Label>
                    <Input
                      value={form.nom}
                      onChange={(e) => setForm({ ...form, nom: e.target.value })}
                      placeholder="Nom"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label>Prénoms *</Label>
                    <Input
                      value={form.prenoms}
                      onChange={(e) => setForm({ ...form, prenoms: e.target.value })}
                      placeholder="Prénoms"
                    />
                  </div>
                </div>
                <div className="space-y-1.5">
                  <Label>Email *</Label>
                  <Input
                    type="email"
                    value={form.email}
                    onChange={(e) => setForm({ ...form, email: e.target.value })}
                    placeholder="agent@acs.ci"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label>Téléphone</Label>
                  <Input
                    value={form.telephone}
                    onChange={(e) => setForm({ ...form, telephone: e.target.value })}
                    placeholder="+225 XX XX XX XX XX"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label>Nouveau mot de passe (optionnel)</Label>
                  {selectedAgent && !selectedAgent.is_active && (
                    <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 mb-2">
                      <p className="text-sm text-amber-800">
                        ⚠️ Cet agent est inactif. Réactivez-le d'abord pour pouvoir modifier son mot de passe.
                      </p>
                    </div>
                  )}
                  <Input
                    type="password"
                    value={form.password}
                    onChange={(e) => setForm({ ...form, password: e.target.value })}
                    placeholder="Laisser vide pour ne pas modifier"
                    disabled={selectedAgent && !selectedAgent.is_active}
                    className={selectedAgent && !selectedAgent.is_active ? "opacity-50 cursor-not-allowed" : ""}
                  />
                </div>

                <Button
                  className="w-full bg-[hsl(222,47%,20%)] hover:bg-[hsl(222,47%,25%)]"
                  onClick={handleUpdate}
                >
                  Mettre à jour l&apos;agent
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      {error && (
        <div className="text-sm text-red-600 bg-red-50 border border-red-200 rounded-md p-3">
          {error}
        </div>
      )}

      {/* Agents list */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {agents.map((a) => {
          const agentRequests = allRequests.filter((r) => r.agentId === a.id);
          const treated = agentRequests.filter((r) => r.status === "traite").length;
          const pending = agentRequests.filter((r) => r.status !== "traite").length;

          return (
            <Card key={a.id} className="border-0 shadow-sm">
              <CardContent className="p-5">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <div className="h-12 w-12 rounded-full bg-[hsl(222,47%,20%)] flex items-center justify-center text-white font-bold text-sm">
                      {a.nom[0]}
                      {a.prenoms[0]}
                    </div>
                    <div>
                      <h3 className="font-semibold">
                        {a.nom} {a.prenoms}
                      </h3>
                      <div className="flex gap-2 mt-0.5">
                      <Badge variant="secondary" className="text-xs">
                        <Shield className="h-3 w-3 mr-1" />
                        Agent
                      </Badge>
                      <Badge 
                        variant={a.is_active ? "default" : "destructive"} 
                        className="text-xs"
                      >
                        {a.is_active ? "✅ Actif" : "⚠️ Inactif"}
                      </Badge>
                    </div>
                    </div>
                  </div>
                  <div className="flex gap-1">
                    <Button 
                      variant="ghost" 
                      size="icon" 
                      className="h-8 w-8"
                      onClick={() => handleEdit(a)}
                    >
                      <Edit className="h-4 w-4 text-gray-400" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className={`h-8 w-8 ${a.is_active ? "text-green-600 hover:text-green-700" : "text-red-600 hover:text-red-700"}`}
                      onClick={() => handleToggle(a)}
                      title={a.is_active ? "Désactiver l'agent" : "Activer l'agent"}
                    >
                      <Power className="h-4 w-4" />
                    </Button>
                  </div>
                </div>

                <div className="mt-4 space-y-2 text-sm">
                  <div className="flex items-center gap-2 text-gray-500">
                    <Mail className="h-3.5 w-3.5" />
                    {a.email}
                  </div>
                  <div className="flex items-center gap-2 text-gray-500">
                    <Phone className="h-3.5 w-3.5" />
                    {a.telephone}
                  </div>
                </div>

                <div className="mt-4 pt-3 border-t flex justify-between text-sm">
                  <div>
                    <span className="text-gray-400">Requêtes traitées</span>
                    <p className="font-semibold text-green-600">{treated}</p>
                  </div>
                  <div>
                    <span className="text-gray-400">En cours</span>
                    <p className="font-semibold text-amber-600">{pending}</p>
                  </div>
                  <div>
                    <span className="text-gray-400">Membre depuis</span>
                    <p className="font-semibold">{new Date(a.createdAt).toLocaleDateString('fr-FR')}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {agents.length === 0 && !loading && (
        <div className="text-center py-12">
          <Users className="h-12 w-12 text-gray-200 mx-auto mb-3" />
          <p className="text-gray-400">Aucun agent trouvé</p>
        </div>
      )}

      {loading && (
        <div className="text-center text-gray-400 py-4">Chargement...</div>
      )}

      <div className="mt-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 text-sm text-gray-600">
        <div>
          {totalCount > 0 ? (
            <span>
              Page {page} / {totalPages} — {agents.length} agents affichés sur {totalCount}
            </span>
          ) : (
            <span>0 agent</span>
          )}
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={handlePrev} disabled={!canGoPrev || loading}>
            Précédent
          </Button>
          <Button variant="outline" size="sm" onClick={handleNext} disabled={!canGoNext || loading}>
            Suivant
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState, useCallback } from "react";
import { Shield, RefreshCw } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useAuditLogs } from "@/hooks/use-api-data";
import { format } from "date-fns";
import { fr } from "date-fns/locale";

const PAGE_SIZE = 25;

export default function AdminAuditPage() {
  const [page, setPage] = useState(1);
  const { data: paginatedLogs, loading, error, refetch } = useAuditLogs({ page, pageSize: PAGE_SIZE });

  const rows = useMemo(() => paginatedLogs.results ?? [], [paginatedLogs]);
  const totalCount = paginatedLogs.count ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));

  const canGoPrev = page > 1;
  const canGoNext = page < totalPages;

  const handlePrev = useCallback(() => {
    if (canGoPrev) {
      setPage((p) => Math.max(1, p - 1));
    }
  }, [canGoPrev]);

  const handleNext = useCallback(() => {
    if (canGoNext) {
      setPage((p) => p + 1);
    }
  }, [canGoNext]);

  const formatState = (value: unknown) => {
    if (typeof value === "boolean") {
      return value ? "Activé" : "Désactivé";
    }
    if (value === null || value === undefined) return "—";
    return String(value);
  };

  const renderMetadata = (action: string, metadata: Record<string, unknown>) => {
    if (metadata && typeof metadata === "object" && "from" in metadata && "to" in metadata) {
      return (
        <span>
          Statut :
          <span className="font-semibold mx-1">{formatState(metadata.from)}</span>
          →
          <span className="font-semibold mx-1">{formatState(metadata.to)}</span>
        </span>
      );
    }

    if (action === "creation" && metadata.role) {
      return (
        <span>
          Rôle attribué : <span className="font-semibold capitalize">{String(metadata.role)}</span>
        </span>
      );
    }

    if (metadata.reason) {
      return (
        <span>
          Motif : <span className="font-semibold">{String(metadata.reason)}</span>
        </span>
      );
    }

    if (Object.keys(metadata || {}).length === 0) {
      return <span className="text-gray-400">–</span>;
    }

    return (
      <pre className="bg-gray-50 rounded px-2 py-1 text-[11px] leading-snug overflow-x-auto">
        {JSON.stringify(metadata, null, 2)}
      </pre>
    );
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Shield className="h-6 w-6 text-red-500" />
            Journal d'audit
          </h1>
          <p className="text-gray-500 mt-1">
            Historique des actions sensibles réalisées par les administrateurs et agents.
          </p>
        </div>
        <Button variant="outline" onClick={refetch} disabled={loading}>
          <RefreshCw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} />
          Actualiser
        </Button>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Dernières entrées</CardTitle>
        </CardHeader>
        <CardContent>
          {error && (
            <div className="mb-4 text-sm text-red-600">{error}</div>
          )}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-gray-500 border-b">
                  <th className="py-3 pr-4">Date</th>
                  <th className="py-3 pr-4">Action</th>
                  <th className="py-3 pr-4">Effectuée par</th>
                  <th className="py-3 pr-4">Cible</th>
                  <th className="py-3">Détails</th>
                </tr>
              </thead>
              <tbody>
                {rows.length === 0 && !loading && (
                  <tr>
                    <td colSpan={5} className="py-6 text-center text-gray-400">
                      Aucune entrée d'audit disponible.
                    </td>
                  </tr>
                )}
                {rows.map((log) => (
                  <tr key={log.id} className="border-b last:border-0">
                    <td className="py-3 pr-4 text-gray-600">
                      {format(new Date(log.createdAt), "dd MMM yyyy HH:mm", { locale: fr })}
                    </td>
                    <td className="py-3 pr-4">
                      <Badge variant="secondary" className="capitalize">
                        {log.action.replace(/_/g, " ")}
                      </Badge>
                    </td>
                    <td className="py-3 pr-4 text-gray-700">
                      {log.performedBy ?? "Système"}
                    </td>
                    <td className="py-3 pr-4 text-gray-700">{log.targetUser}</td>
                    <td className="py-3 text-gray-600 text-xs">
                      {renderMetadata(log.action, log.metadata)}
                    </td>
                  </tr>
                ))}
                {loading && (
                  <tr>
                    <td colSpan={5} className="py-6 text-center text-gray-400">
                      Chargement...
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          <div className="mt-4 flex items-center justify-between text-sm text-gray-600">
            <div>
              {totalCount > 0 ? (
                <span>
                  Page {page} / {totalPages} — {rows.length} éléments affichés sur {totalCount}
                </span>
              ) : (
                <span>0 entrée</span>
              )}
            </div>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={handlePrev} disabled={!canGoPrev || loading}>
                Précédent
              </Button>
              <Button variant="outline" size="sm" onClick={handleNext} disabled={!canGoNext || loading}>
                Suivant
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
  LayoutDashboard,
  Users,
  Shield,
  LogOut,
  Menu,
  X,
  Activity,
  Bell,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Separator } from "@/components/ui/separator";
import { useAuthStore } from "@/stores/auth-store";
import { toast } from "sonner";
import { NotificationsDropdown } from "@/components/notifications-dropdown";
import { cn } from "@/lib/utils";

const navigation = [
  { name: "Supervision", href: "/admin/dashboard", icon: LayoutDashboard },
  { name: "Gestion des agents", href: "/admin/agents", icon: Users },
  { name: "Journal d'audit", href: "/admin/audit", icon: Shield },
];

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const { user, isAuthenticated, loading, logout, initialized } = useAuthStore();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Auth guard — redirect via useEffect to avoid setState-during-render
  const shouldRedirect = !initialized || !isAuthenticated || !user || user.role !== "admin";
  useEffect(() => {
    if (loading || !initialized) return;
    if (!isAuthenticated || !user || user.role !== "admin") {
      router.replace("/login");
    }
  }, [initialized, isAuthenticated, user, loading, router]);

  if (loading || !initialized || shouldRedirect) return null;

  const handleLogout = () => {
    logout();
    router.push("/login");
  };

  const SidebarContent = () => (
    <div className="flex flex-col h-full">
      <div className="p-6 pb-4">
        <div className="flex items-center gap-3">
          <Shield className="h-8 w-8 text-amber-400" />
          <div>
            <h1 className="text-lg font-bold text-white">ACS Admin</h1>
            <p className="text-amber-400 text-xs font-medium">Panneau d&apos;administration</p>
          </div>
        </div>
      </div>

      <Separator className="bg-white/10" />

      <div className="p-4">
        <div className="flex items-center gap-3">
          <Avatar className="h-10 w-10 bg-red-400/20 border border-red-400/30">
            <AvatarFallback className="bg-red-400/20 text-red-400 text-sm font-semibold">
              AD
            </AvatarFallback>
          </Avatar>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-white truncate">
              {user?.nom} {user?.prenoms}
            </p>
            <p className="text-xs text-white/50">Administrateur</p>
          </div>
        </div>
      </div>

      <Separator className="bg-white/10" />

      <nav className="flex-1 p-3 space-y-1">
        {navigation.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={() => setSidebarOpen(false)}
              className={cn(
                "flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all",
                isActive
                  ? "bg-amber-400/15 text-amber-400"
                  : "text-white/70 hover:text-white hover:bg-white/5"
              )}
            >
              <item.icon className="h-4 w-4 flex-shrink-0" />
              {item.name}
            </Link>
          );
        })}
      </nav>

      <Separator className="bg-white/10" />

      <div className="p-3">
        <button
          onClick={handleLogout}
          className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium text-red-400/70 hover:text-red-400 hover:bg-red-400/10 w-full transition-all"
        >
          <LogOut className="h-4 w-4" />
          Déconnexion
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-50">
      {sidebarOpen && (
        <div className="fixed inset-0 z-50 lg:hidden">
          <div className="fixed inset-0 bg-black/50" onClick={() => setSidebarOpen(false)} />
          <div className="fixed inset-y-0 left-0 w-72 bg-[hsl(222,47%,15%)]">
            <button
              onClick={() => setSidebarOpen(false)}
              className="absolute top-4 right-4 text-white/50 hover:text-white"
            >
              <X className="h-5 w-5" />
            </button>
            <SidebarContent />
          </div>
        </div>
      )}

      <div className="hidden lg:fixed lg:inset-y-0 lg:flex lg:w-72">
        <div className="flex-1 bg-[hsl(222,47%,15%)]">
          <SidebarContent />
        </div>
      </div>

      <div className="lg:pl-72">
        <header className="sticky top-0 z-40 bg-white border-b border-gray-200">
          <div className="flex items-center justify-between h-16 px-4 sm:px-6">
            <Button
              variant="ghost"
              size="icon"
              className="lg:hidden"
              onClick={() => setSidebarOpen(true)}
            >
              <Menu className="h-5 w-5" />
            </Button>
            <div className="hidden lg:flex items-center gap-2">
              <Activity className="h-4 w-4 text-red-500" />
              <h2 className="text-lg font-semibold text-gray-900">Administration</h2>
            </div>
            <div className="flex items-center gap-3">
              <NotificationsDropdown initialCount={3} />
              <span className="text-sm text-gray-500 hidden sm:block">Administrateur</span>
              <Avatar className="h-8 w-8">
                <AvatarFallback className="bg-red-600 text-white text-xs">AD</AvatarFallback>
              </Avatar>
            </div>
          </div>
        </header>

        <main className="p-4 sm:p-6 lg:p-8">{children}</main>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState, useEffect } from "react";
import {
  Users,
  Search,
  Plus,
  Phone,
  Mail,
  Shield,
  Check,
  AlertTriangle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";

import { usePaginatedUsers, useEmissions, useRequests } from "@/hooks/use-api-data";
import { usersApi } from "@/lib/api";
import { PROFESSION_LABELS, REQUEST_TYPE_LABELS } from "@/lib/types";

const PAGE_SIZE = 15;
type Segment = "magistrats" | "premium" | "standard" | "prospects";

const initialFormState = { nom: "", prenoms: "", email: "", telephone: "", telephone2: "" };

const formatCurrency = (value: number) => `${new Intl.NumberFormat("fr-FR").format(value)} FCFA`;

export default function AgentClientsPage() {
  const [page, setPage] = useState(1);
  const [segment, setSegment] = useState<Segment>("magistrats");
  const [search, setSearch] = useState("");
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [form, setForm] = useState(initialFormState);

  const { data: paginatedUsers, loading, error, refetch } = usePaginatedUsers({
    page,
    pageSize: PAGE_SIZE,
    search: search.trim() || undefined,
    role: segment === "prospects" ? "prospect" : "client",
    profession_type: segment === "magistrats" ? "magistrat" : undefined,
    exclude_profession_type: segment !== "magistrats" && segment !== "prospects" ? "magistrat" : undefined,
    risk_level: segment === "premium" ? "premium" : segment === "standard" ? "standard" : undefined,
  });

  const clients = paginatedUsers.results ?? [];
  const totalCount = paginatedUsers.count ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));
  const canGoPrev = page > 1;
  const canGoNext = page < totalPages;

  useEffect(() => {
    if (selectedClientId && !clients.some((client) => client.id === selectedClientId)) {
      setSelectedClientId(null);
    }
  }, [clients, selectedClientId]);

  const { data: emissions } = useEmissions();
  const { data: requests } = useRequests();

  const selectedClient = useMemo(() => clients.find((client) => client.id === selectedClientId) ?? null, [clients, selectedClientId]);

  const selectedEmissions = useMemo(() => {
    if (!selectedClient) return [];
    return emissions.filter((emission) => emission.clientId === selectedClient.id);
  }, [emissions, selectedClient]);

  const selectedRequests = useMemo(() => {
    if (!selectedClient) return [];
    return requests.filter((request) => request.clientId === selectedClient.id);
  }, [requests, selectedClient]);

  const selectedStats = useMemo(() => {
    if (!selectedClient) return null;
    const primeTotale = selectedEmissions.reduce((sum, emission) => sum + emission.primeTTC, 0);
    const primePayee = selectedEmissions.reduce(
      (sum, emission) => sum + emission.paiements.reduce((pSum, payment) => pSum + payment.montantRegle, 0),
      0
    );
    return {
      primeTotale,
      primePayee,
      primeAPayer: primeTotale - primePayee,
    };
  }, [selectedClient, selectedEmissions]);

  const handleCreateClient = async () => {
    if (!form.nom || !form.prenoms || !form.email || !form.telephone) {
      toast.error("Veuillez remplir les champs obligatoires");
      return;
    }

    try {
      await usersApi.createClient({
        nom: form.nom,
        prenoms: form.prenoms,
        email: form.email,
        telephone: form.telephone,
        telephone2: form.telephone2,
        password: "Temp@1234",
      });
      toast.success("Client créé avec succès");
      setForm(initialFormState);
      setShowAddDialog(false);
      refetch();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Erreur lors de la création");
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Users className="h-6 w-6" />
            Assurés & Prospects
          </h1>
          <p className="text-gray-500 mt-1">
            {totalCount} enregistrements • Segment {segment}
          </p>
        </div>
        <div className="flex gap-3 w-full sm:w-auto">
          <div className="relative flex-1 sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Rechercher..."
              value={search}
              onChange={(event) => {
                setPage(1);
                setSearch(event.target.value);
              }}
              className="pl-9"
            />
          </div>
          <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
            <DialogTrigger asChild>
              <Button className="bg-[hsl(222,47%,20%)] hover:bg-[hsl(222,47%,25%)]">
                <Plus className="h-4 w-4 mr-2" /> Ajouter
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Ajouter un client</DialogTitle>
              </DialogHeader>
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label>Nom *</Label>
                    <Input value={form.nom} onChange={(event) => setForm({ ...form, nom: event.target.value })} />
                  </div>
                  <div>
                    <Label>Prénoms *</Label>
                    <Input value={form.prenoms} onChange={(event) => setForm({ ...form, prenoms: event.target.value })} />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label>Téléphone *</Label>
                    <Input value={form.telephone} onChange={(event) => setForm({ ...form, telephone: event.target.value })} />
                  </div>
                  <div>
                    <Label>Téléphone 2</Label>
                    <Input value={form.telephone2} onChange={(event) => setForm({ ...form, telephone2: event.target.value })} />
                  </div>
                </div>
                <div>
                  <Label>Email *</Label>
                  <Input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} />
                </div>
                <Button onClick={handleCreateClient} className="w-full">
                  Enregistrer
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2 border-0 shadow-sm">
          <CardHeader>
            <div className="flex flex-col gap-3">
              <div className="flex justify-between items-center">
                <CardTitle className="text-base flex items-center gap-2">
                  <Shield className="h-5 w-5 text-blue-500" />
                  Liste des clients
                </CardTitle>
                <Tabs value={segment} onValueChange={(value) => {
                  setSegment(value as Segment);
                  setPage(1);
                }}>
                  <TabsList className="grid grid-cols-4">
                    <TabsTrigger value="magistrats">Magistrats</TabsTrigger>
                    <TabsTrigger value="premium">Premium</TabsTrigger>
                    <TabsTrigger value="standard">Standard</TabsTrigger>
                    <TabsTrigger value="prospects">Prospects</TabsTrigger>
                  </TabsList>
                </Tabs>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            {loading ? (
              <p className="text-center text-gray-400 py-12">Chargement...</p>
            ) : error ? (
              <p className="text-center text-red-500 py-12">{error}</p>
            ) : clients.length === 0 ? (
              <p className="text-center text-gray-400 py-12">Aucun résultat</p>
            ) : (
              <div className="space-y-3">
                {clients.map((client) => (
                  <button
                    key={client.id}
                    onClick={() => setSelectedClientId(client.id)}
                    className={`w-full text-left border rounded-lg p-4 transition hover:border-blue-400 ${
                      selectedClientId === client.id ? "border-blue-500" : "border-gray-200"
                    }`}
                  >
                    <div className="flex justify-between items-start">
                      <div>
                        <p className="font-semibold text-gray-900">{client.nom} {client.prenoms}</p>
                        <p className="text-sm text-gray-500">{client.profession}</p>
                      </div>
                      <Badge variant={client.verified ? "default" : "secondary"}>
                        {client.verified ? "Vérifié" : "Prospect"}
                      </Badge>
                    </div>
                    <div className="mt-2 flex flex-wrap gap-4 text-sm text-gray-500">
                      <span className="flex items-center gap-1">
                        <Phone className="h-3 w-3" /> {client.telephone}
                      </span>
                      <span className="flex items-center gap-1">
                        <Mail className="h-3 w-3" /> {client.email}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            )}
            <div className="flex items-center justify-between mt-4 text-sm text-gray-600">
              <span>Page {page} / {totalPages}</span>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" disabled={!canGoPrev} onClick={() => setPage((current) => current - 1)}>
                  Précédent
                </Button>
                <Button variant="outline" size="sm" disabled={!canGoNext} onClick={() => setPage((current) => current + 1)}>
                  Suivant
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="border-0 shadow-sm">
          <CardHeader>
            <CardTitle className="text-base">Détails</CardTitle>
          </CardHeader>
          <CardContent>
            {selectedClient ? (
              <div className="space-y-4">
                <div>
                  <p className="font-semibold text-lg">{selectedClient.nom} {selectedClient.prenoms}</p>
                  <p className="text-sm text-gray-500">{selectedClient.profession}</p>
                </div>
                <div className="bg-gray-50 rounded-lg p-3 space-y-1 text-sm">
                  <div className="flex justify-between">
                    <span className="text-gray-500">Catégorie</span>
                    <Badge variant="secondary">{PROFESSION_LABELS[selectedClient.professionType]}</Badge>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-500">Email</span>
                    <span className="font-medium">{selectedClient.email}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-500">Téléphone</span>
                    <span className="font-medium">{selectedClient.telephone}</span>
                  </div>
                </div>

                {selectedStats && (
                  <div className="space-y-3">
                    <div className="grid grid-cols-2 gap-3">
                      <div className="bg-green-50 p-3 rounded-lg">
                        <p className="text-xs text-gray-500">Prime totale</p>
                        <p className="text-lg font-semibold text-green-700">{formatCurrency(selectedStats.primeTotale)}</p>
                      </div>
                      <div className="bg-blue-50 p-3 rounded-lg">
                        <p className="text-xs text-gray-500">Prime payée</p>
                        <p className="text-lg font-semibold text-blue-700">{formatCurrency(selectedStats.primePayee)}</p>
                      </div>
                    </div>
                    <div className={`p-3 rounded-lg text-center text-white ${selectedStats.primeAPayer > 0 ? "bg-red-500" : "bg-emerald-500"}`}>
                      Solde {formatCurrency(selectedStats.primeAPayer)}
                    </div>
                  </div>
                )}

                {selectedEmissions.length > 0 && (
                  <div>
                    <p className="text-sm font-semibold mb-2">Contrats</p>
                    <div className="space-y-2">
                      {selectedEmissions.map((emission) => (
                        <div key={emission.id} className="text-sm p-2 bg-gray-50 rounded">
                          <div className="flex justify-between">
                            <span className="font-medium">{emission.risque}</span>
                            <span className="text-xs text-gray-400">{emission.numPolice}</span>
                          </div>
                          <p className="text-xs text-gray-500">{emission.compagnie} • Échéance {emission.echeance}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {selectedRequests.length > 0 && (
                  <div>
                    <p className="text-sm font-semibold mb-2">Requêtes ({selectedRequests.length})</p>
                    <div className="space-y-2">
                      {selectedRequests.map((request) => (
                        <div key={request.id} className="flex justify-between items-center text-sm p-2 bg-gray-50 rounded">
                          <div>
                            <p className="font-medium">{REQUEST_TYPE_LABELS[request.type]}</p>
                            <p className="text-xs text-gray-400">N° {request.numero}</p>
                          </div>
                          <Badge variant="secondary">{request.status}</Badge>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center text-gray-400 py-10">
                <AlertTriangle className="h-6 w-6 mx-auto mb-3" />
                Sélectionnez un client pour afficher les détails.
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  FileSpreadsheet,
  Search,
  Plus,
  Download,
  Filter,
  Eye,
  CreditCard,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useEmissions, useUsers } from "@/hooks/use-api-data";
import { emissionsApi, paiementsApi } from "@/lib/api";
import { RISQUES, COMPAGNIES } from "@/lib/types";
import { toast } from "sonner";

export default function AgentEmissionsPage() {
  const { data: allEmissions, refetch: refetchEmissions } = useEmissions();
  const { data: allUsers } = useUsers();
  const [search, setSearch] = useState("");
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [paymentDialogId, setPaymentDialogId] = useState<string | null>(null);
  const [paymentAmount, setPaymentAmount] = useState("");
  const [paymentRef, setPaymentRef] = useState("");
  const [paymentObs, setPaymentObs] = useState("");

  // New emission form state
  const [emForm, setEmForm] = useState({
    date: new Date().toISOString().split("T")[0],
    situation: "",
    client: "",
    risque: "",
    compagnie: "",
    numFacture: "",
    numPolice: "",
    effet: "",
    echeance: "",
    primeNette: "",
    primeTtc: "",
    marque: "",
    immatriculation: "",
  });

  const formatCurrency = (amount: number) =>
    new Intl.NumberFormat("fr-FR").format(amount) + " FCFA";

  const filtered = allEmissions.filter(
    (e) =>
      e.clientNom.toLowerCase().includes(search.toLowerCase()) ||
      e.risque.toLowerCase().includes(search.toLowerCase()) ||
      e.compagnie.toLowerCase().includes(search.toLowerCase()) ||
      e.numPolice.toLowerCase().includes(search.toLowerCase()) ||
      e.numFacture.toLowerCase().includes(search.toLowerCase()) ||
      e.marque.toLowerCase().includes(search.toLowerCase()) ||
      e.immatriculation.toLowerCase().includes(search.toLowerCase())
  );

  const clients = allUsers.filter(
    (u) => u.role === "client" || u.role === "prospect"
  );

  const handleExport = () => {
    window.open(emissionsApi.exportUrl(), "_blank");
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <FileSpreadsheet className="h-6 w-6" />
            Émissions
          </h1>
          <p className="text-gray-500 mt-1">
            {allEmissions.length} émission
            {allEmissions.length > 1 ? "s" : ""} en portefeuille
          </p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Rechercher..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9"
            />
          </div>
          <Button variant="outline" size="icon" onClick={handleExport}>
            <Download className="h-4 w-4" />
          </Button>
          <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
            <DialogTrigger asChild>
              <Button className="bg-[hsl(222,47%,20%)] hover:bg-[hsl(222,47%,25%)]">
                <Plus className="h-4 w-4 mr-1" /> Nouvelle émission
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
              <DialogHeader>
                <DialogTitle>Nouvelle émission</DialogTitle>
              </DialogHeader>
              <div className="space-y-4 pt-2">
                <div className="space-y-1.5">
                  <Label>Date de saisie *</Label>
                  <Input type="date" value={emForm.date} onChange={(e) => setEmForm({ ...emForm, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <Label>Situation *</Label>
                  <Select value={emForm.situation} onValueChange={(v) => setEmForm({ ...emForm, situation: v })}>
                    <SelectTrigger>
                      <SelectValue placeholder="Sélectionnez..." />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="Affaire nouvelle">Affaire nouvelle</SelectItem>
                      <SelectItem value="Incorporation">Incorporation</SelectItem>
                      <SelectItem value="Retrait">Retrait</SelectItem>
                      <SelectItem value="Renouvellement">Renouvellement</SelectItem>
                      <SelectItem value="Modification">Modification</SelectItem>
                    </SelectContent>
