                <div className="space-y-1.5">
                  <Label>Compagnie *</Label>
                  <Select value={emForm.compagnie} onValueChange={(v) => setEmForm({ ...emForm, compagnie: v })}>
                    <SelectTrigger>
                      <SelectValue placeholder="Sélectionnez..." />
                    </SelectTrigger>
                    <SelectContent>
                      {COMPAGNIES.map((c) => (
                        <SelectItem key={c} value={c}>
                          {c}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1.5">
                    <Label>N° Facture *</Label>
                    <Input placeholder="FA-2025-XXXX" value={emForm.numFacture} onChange={(e) => setEmForm({ ...emForm, numFacture: e.target.value })} />
                  </div>
                  <div className="space-y-1.5">
                    <Label>N° Police *</Label>
                    <Input placeholder="POL-XXXX-XXXXX" value={emForm.numPolice} onChange={(e) => setEmForm({ ...emForm, numPolice: e.target.value })} />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1.5">
                    <Label>Date d&apos;effet *</Label>
                    <Input type="date" value={emForm.effet} onChange={(e) => setEmForm({ ...emForm, effet: e.target.value })} />
                  </div>
                  <div className="space-y-1.5">
                    <Label>Date d&apos;échéance *</Label>
                    <Input type="date" value={emForm.echeance} onChange={(e) => setEmForm({ ...emForm, echeance: e.target.value })} />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1.5">
                    <Label>Prime nette (FCFA) *</Label>
                    <Input type="number" placeholder="0" value={emForm.primeNette} onChange={(e) => setEmForm({ ...emForm, primeNette: e.target.value })} />
                  </div>
                  <div className="space-y-1.5">
                    <Label>Prime TTC (FCFA) *</Label>
                    <Input type="number" placeholder="0" value={emForm.primeTtc} onChange={(e) => setEmForm({ ...emForm, primeTtc: e.target.value })} />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1.5">
                    <Label>Marque</Label>
                    <Input placeholder="Marque du véhicule" value={emForm.marque} onChange={(e) => setEmForm({ ...emForm, marque: e.target.value })} />
