                      toast.error("Veuillez remplir tous les champs obligatoires");
                      return;
                    }
                    try {
                      await emissionsApi.create({
                        date: emForm.date,
                        situation: emForm.situation || "Affaire nouvelle",
                        client: Number(emForm.client),
                        risque: emForm.risque,
                        compagnie: emForm.compagnie,
                        num_facture: emForm.numFacture,
                        num_police: emForm.numPolice,
                        effet: emForm.effet,
                        echeance: emForm.echeance,
                        prime_nette: Number(emForm.primeNette),
                        prime_ttc: Number(emForm.primeTtc),
                        marque: emForm.marque || "-",
                        immatriculation: emForm.immatriculation || "-",
                      });
                      toast.success("Émission créée avec succès");
                      setShowAddDialog(false);
                      refetchEmissions();
                    } catch (err: unknown) {
                      toast.error(err instanceof Error ? err.message : "Erreur lors de la création");
