                  Enregistrer l&apos;émission
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      {/* Emissions table */}
      <Card className="border-0 shadow-sm">
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b bg-gray-50">
                  <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Client
                  </th>
                  <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Risque
                  </th>
                  <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Compagnie
                  </th>
                  <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Police
                  </th>
                  <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Effet
                  </th>
                  <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Échéance
                  </th>
                  <th className="text-right text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    TTC
                  </th>
                  <th className="text-right text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Payé
                  </th>
                  <th className="text-right text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Solde
                  </th>
                  <th className="text-right text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Commission
                  </th>
                  <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((e) => {
                  const totalPaye = e.paiements.reduce(
                    (s, p) => s + p.montantRegle,
                    0
                  );
                  const solde = e.primeTTC - totalPaye;
                  const risqueInfo = RISQUES.find((r) => r.nom === e.risque);
                  const commission = risqueInfo
                    ? (e.primeNette * risqueInfo.tauxCommission) / 100
                    : 0;
                  const isExpired = new Date(e.echeance) < new Date();

                  return (
                    <tr
                      key={e.id}
                      className="border-b last:border-0 hover:bg-gray-50/50"
                    >
                      <td className="px-4 py-3 text-sm font-medium">
                        {e.clientNom}
                      </td>
                      <td className="px-4 py-3 text-sm">{e.risque}</td>
                      <td className="px-4 py-3 text-sm">{e.compagnie}</td>
                      <td className="px-4 py-3 text-xs font-mono">
                        {e.numPolice}
                      </td>
                      <td className="px-4 py-3 text-sm">{e.effet}</td>
                      <td className="px-4 py-3">
                        <Badge
                          variant={isExpired ? "destructive" : "secondary"}
                          className="text-xs"
                        >
                          {e.echeance}
                        </Badge>
                      </td>
                      <td className="px-4 py-3 text-right text-sm font-semibold">
                        {formatCurrency(e.primeTTC)}
                      </td>
                      <td className="px-4 py-3 text-right text-sm text-green-600">
                        {formatCurrency(totalPaye)}
                      </td>
                      <td
                        className={`px-4 py-3 text-right text-sm font-semibold ${
                          solde > 0 ? "text-red-600" : "text-green-600"
                        }`}
                      >
                        {formatCurrency(solde)}
                      </td>
                      <td className="px-4 py-3 text-right text-sm text-purple-600">
                        {formatCurrency(commission)}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <div className="flex items-center justify-center gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() =>
                              setExpandedId(expandedId === e.id ? null : e.id)
                            }
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          {solde > 0 && (
                            <Button
                              variant="ghost"
                              size="sm"
                              className="text-green-600"
                              onClick={() => {
                                setPaymentDialogId(e.id);
                                setPaymentAmount("");
                                setPaymentRef("");
                                setPaymentObs("");
                              }}
                            >
                              <CreditCard className="h-4 w-4" />
                            </Button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr className="bg-gray-50 font-semibold">
                  <td colSpan={6} className="px-4 py-3 text-sm">
                    TOTAUX
                  </td>
                  <td className="px-4 py-3 text-right text-sm">
                    {formatCurrency(
                      filtered.reduce((s, e) => s + e.primeTTC, 0)
                    )}
                  </td>
                  <td className="px-4 py-3 text-right text-sm text-green-600">
                    {formatCurrency(
                      filtered.reduce(
                        (s, e) =>
                          s +
                          e.paiements.reduce(
                            (ps, p) => ps + p.montantRegle,
                            0
                          ),
                        0
                      )
                    )}
                  </td>
                  <td className="px-4 py-3 text-right text-sm text-red-600">
                    {formatCurrency(
                      filtered.reduce((s, e) => {
                        const paid = e.paiements.reduce(
                          (ps, p) => ps + p.montantRegle,
                          0
                        );
                        return s + (e.primeTTC - paid);
                      }, 0)
                    )}
                  </td>
                  <td className="px-4 py-3 text-right text-sm text-purple-600">
                    {formatCurrency(
                      filtered.reduce((s, e) => {
                        const r = RISQUES.find((r) => r.nom === e.risque);
                        return s + (r ? (e.primeNette * r.tauxCommission) / 100 : 0);
                      }, 0)
                    )}
                  </td>
                  <td></td>
                </tr>
              </tfoot>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Payment recording dialog */}
      <Dialog open={!!paymentDialogId} onOpenChange={(open) => !open && setPaymentDialogId(null)}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>Enregistrer un paiement</DialogTitle>
          </DialogHeader>
          {paymentDialogId && (() => {
            const em = allEmissions.find((e) => e.id === paymentDialogId);
            if (!em) return null;
            const totalPaye = em.paiements.reduce((s, p) => s + p.montantRegle, 0);
            const solde = em.primeTTC - totalPaye;
            return (
              <div className="space-y-4 pt-2">
                <div className="text-sm bg-gray-50 p-3 rounded-lg space-y-1">
                  <p><span className="text-gray-400">Client:</span> <strong>{em.clientNom}</strong></p>
                  <p><span className="text-gray-400">Police:</span> {em.numPolice}</p>
                  <p><span className="text-gray-400">Solde restant:</span> <strong className="text-red-600">{formatCurrency(solde)}</strong></p>
                </div>
                <div className="space-y-1.5">
                  <Label>Montant réglé (FCFA) *</Label>
                  <Input type="number" placeholder="0" value={paymentAmount} onChange={(e) => setPaymentAmount(e.target.value)} />
                </div>
                <div className="space-y-1.5">
                  <Label>Référence paiement *</Label>
                  <Input placeholder="PAY-2025-XXX" value={paymentRef} onChange={(e) => setPaymentRef(e.target.value)} />
                </div>
                <div className="space-y-1.5">
                  <Label>Observations</Label>
                  <Input placeholder="Wave, Orange Money, Espèces..." value={paymentObs} onChange={(e) => setPaymentObs(e.target.value)} />
                </div>
                <Button
                  className="w-full bg-green-600 hover:bg-green-700 text-white"
                  onClick={async () => {
                    if (!paymentAmount || !paymentRef) {
                      toast.error("Veuillez remplir le montant et la référence");
                      return;
                    }
                    try {
                      await paiementsApi.create({
                        emission: Number(em.id),
                        date_reglement: new Date().toISOString().split("T")[0],
                        reference: paymentRef,
                        montant_regle: Number(paymentAmount),
                        observations: paymentObs,
                      });
                      toast.success(`Paiement de ${formatCurrency(Number(paymentAmount))} enregistré`);
                      setPaymentDialogId(null);
                      refetchEmissions();
                    } catch (err: unknown) {
                      toast.error(err instanceof Error ? err.message : "Erreur lors de l'enregistrement");
                    }
                  }}
                >
                  <CreditCard className="h-4 w-4 mr-2" /> Enregistrer le paiement
                </Button>
              </div>
            );
          })()}
        </DialogContent>
      </Dialog>

      {filtered.length === 0 && (
        <div className="text-center py-12">
          <FileSpreadsheet className="h-12 w-12 text-gray-200 mx-auto mb-3" />
          <p className="text-gray-400">Aucune émission trouvée</p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
  LayoutDashboard,
  Users,
  FileSpreadsheet,
  ClipboardList,
  Shield,
  LogOut,
  Menu,
  X,
  Settings,
  Bell,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Separator } from "@/components/ui/separator";
import { useAuthStore } from "@/stores/auth-store";
import { toast } from "sonner";
import { NotificationsDropdown } from "@/components/notifications-dropdown";
import { cn } from "@/lib/utils";

const navigation = [
  { name: "Tableau de bord", href: "/agent/dashboard", icon: LayoutDashboard },
  { name: "Assurés / Prospects", href: "/agent/clients", icon: Users },
  { name: "Émissions", href: "/agent/emissions", icon: FileSpreadsheet },
  { name: "Requêtes clients", href: "/agent/requests", icon: ClipboardList },
];

export default function AgentLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const { user, isAuthenticated, loading, logout, initialized } = useAuthStore();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Auth guard — redirect via useEffect to avoid setState-during-render
  const shouldRedirect =
    !initialized || !isAuthenticated || !user || (user.role !== "agent" && user.role !== "admin");
  useEffect(() => {
    if (loading || !initialized) return;
    if (!isAuthenticated || !user) {
      router.replace("/login");
    } else if (user.role !== "agent" && user.role !== "admin") {
      router.replace("/client/dashboard");
    }
  }, [initialized, isAuthenticated, user, loading, router]);

  if (loading || !initialized || shouldRedirect) return null;

  const handleLogout = () => {
    logout();
    router.push("/login");
  };

  const initials = `${user?.nom?.[0] ?? "A"}${user?.prenoms?.[0] ?? "C"}`;

  const SidebarContent = () => (
    <div className="flex flex-col h-full">
      <div className="p-6 pb-4">
        <div className="flex items-center gap-3">
          <Shield className="h-8 w-8 text-amber-400" />
          <div>
            <h1 className="text-lg font-bold text-white">ACS Agent</h1>
            <p className="text-amber-400 text-xs font-medium">Gestion des opérations</p>
          </div>
        </div>
      </div>

      <Separator className="bg-white/10" />

      <div className="p-4">
        <div className="flex items-center gap-3">
          <Avatar className="h-10 w-10 bg-amber-400/20 border border-amber-400/30">
            <AvatarFallback className="bg-amber-400/20 text-amber-400 text-sm font-semibold">
              {initials}
            </AvatarFallback>
          </Avatar>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-white truncate">
              {user?.nom} {user?.prenoms}
            </p>
            <p className="text-xs text-white/50">Agent ACS</p>
          </div>
        </div>
      </div>

      <Separator className="bg-white/10" />

      <nav className="flex-1 p-3 space-y-1">
        <p className="px-3 text-[10px] uppercase tracking-wider text-white/30 font-semibold mb-2">
          Menu principal
        </p>
        {navigation.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={() => setSidebarOpen(false)}
              className={cn(
                "flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all",
                isActive
                  ? "bg-amber-400/15 text-amber-400"
                  : "text-white/70 hover:text-white hover:bg-white/5"
              )}
            >
              <item.icon className="h-4 w-4 flex-shrink-0" />
              {item.name}
            </Link>
          );
        })}
      </nav>

      <Separator className="bg-white/10" />

      <div className="p-3 space-y-1">
        <button
          onClick={handleLogout}
          className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium text-red-400/70 hover:text-red-400 hover:bg-red-400/10 w-full transition-all"
        >
          <LogOut className="h-4 w-4" />
          Déconnexion
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-50">
      {sidebarOpen && (
        <div className="fixed inset-0 z-50 lg:hidden">
          <div className="fixed inset-0 bg-black/50" onClick={() => setSidebarOpen(false)} />
          <div className="fixed inset-y-0 left-0 w-72 bg-[hsl(222,47%,15%)]">
            <button
              onClick={() => setSidebarOpen(false)}
              className="absolute top-4 right-4 text-white/50 hover:text-white"
            >
              <X className="h-5 w-5" />
            </button>
            <SidebarContent />
          </div>
        </div>
      )}

      <div className="hidden lg:fixed lg:inset-y-0 lg:flex lg:w-72">
        <div className="flex-1 bg-[hsl(222,47%,15%)]">
          <SidebarContent />
        </div>
      </div>

      <div className="lg:pl-72">
        <header className="sticky top-0 z-40 bg-white border-b border-gray-200">
          <div className="flex items-center justify-between h-16 px-4 sm:px-6">
            <Button
              variant="ghost"
              size="icon"
              className="lg:hidden"
              onClick={() => setSidebarOpen(true)}
            >
              <Menu className="h-5 w-5" />
            </Button>
            <div className="hidden lg:block">
              <h2 className="text-lg font-semibold text-gray-900">Espace Agent ACS</h2>
            </div>
            <div className="flex items-center gap-3">
              <NotificationsDropdown initialCount={4} />
              <span className="text-sm text-gray-500 hidden sm:block">
                {user?.nom} {user?.prenoms}
              </span>
              <Avatar className="h-8 w-8">
                <AvatarFallback className="bg-[hsl(222,47%,20%)] text-white text-xs">
                  {initials}
                </AvatarFallback>
              </Avatar>
            </div>
          </div>
        </header>

        <main className="p-4 sm:p-6 lg:p-8">{children}</main>
      </div>
    </div>
  );
}

"use client";

import { useState, useRef } from "react";
import {
  ClipboardList,
  Search,
  Eye,
  Upload,
  CheckCircle,
  Clock,
  AlertCircle,
  Download,
  FileText,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useRequests } from "@/hooks/use-api-data";
import { requestsApi, documentsApi } from "@/lib/api";
import { REQUEST_TYPE_LABELS, REQUEST_STATUS_LABELS } from "@/lib/types";
import type { ClientRequest } from "@/lib/types";
import { toast } from "sonner";

export default function AgentRequestsPage() {
  const { data: allRequests, refetch: refetchRequests } = useRequests();
  const [search, setSearch] = useState("");
  const [selectedRequest, setSelectedRequest] = useState<ClientRequest | null>(null);
  const [showDetail, setShowDetail] = useState(false);

  const filtered = allRequests.filter(
    (r) =>
      r.numero.toLowerCase().includes(search.toLowerCase()) ||
      r.clientNom.toLowerCase().includes(search.toLowerCase()) ||
      REQUEST_TYPE_LABELS[r.type].toLowerCase().includes(search.toLowerCase())
  );

  const enAttente = filtered.filter((r) => r.status === "en_attente");
  const enCours = filtered.filter((r) => r.status === "en_cours");
  const traites = filtered.filter((r) => r.status === "traite");

  const statusIcon = (status: string) => {
    switch (status) {
      case "en_attente":
        return <Clock className="h-4 w-4 text-yellow-500" />;
      case "en_cours":
        return <AlertCircle className="h-4 w-4 text-blue-500" />;
      case "traite":
        return <CheckCircle className="h-4 w-4 text-green-500" />;
      default:
        return <Clock className="h-4 w-4 text-gray-400" />;
    }
  };

  const statusColor = (status: string) => {
    switch (status) {
      case "en_attente":
        return "bg-yellow-100 text-yellow-800";
      case "en_cours":
        return "bg-blue-100 text-blue-800";
      case "traite":
        return "bg-green-100 text-green-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const openDetail = (r: ClientRequest) => {
    setSelectedRequest(r);
    setShowDetail(true);
  };

  const handleMarkAsTreated = async () => {
    if (!selectedRequest) return;
    try {
      await requestsApi.treat(Number(selectedRequest.id));
      toast.success("Requête marquée comme traitée.");
      setShowDetail(false);
      refetchRequests();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors du traitement");
    }
  };

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleUploadLivrable = () => {
    fileInputRef.current?.click();
  };

  const handleFileSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !selectedRequest) return;
    try {
      await documentsApi.upload(file, Number(selectedRequest.id), true);
      toast.success(`Livrable "${file.name}" téléversé avec succès`);
      refetchRequests();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors du téléversement");
    }
    e.target.value = "";
  };

  const RequestCard = ({ request }: { request: ClientRequest }) => (
    <Card
      className="border-0 shadow-sm hover:shadow-md transition cursor-pointer"
      onClick={() => openDetail(request)}
    >
      <CardContent className="p-4">
        <div className="flex items-start justify-between">
          <div className="flex items-start gap-3">
            {statusIcon(request.status)}
            <div>
              <h3 className="text-sm font-semibold">
                {REQUEST_TYPE_LABELS[request.type]}
              </h3>
              <p className="text-xs text-gray-500 mt-0.5">
                {request.numero} • {request.clientNom}
              </p>
              <p className="text-xs text-gray-400 mt-0.5">
                Soumis le {request.createdAt}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {request.documents.length > 0 && (
              <span className="text-xs text-gray-400 flex items-center gap-1">
                <FileText className="h-3 w-3" />
                {request.documents.length}
              </span>
            )}
            <Badge className={statusColor(request.status)} variant="secondary">
              {REQUEST_STATUS_LABELS[request.status]}
            </Badge>
          </div>
        </div>
      </CardContent>
    </Card>
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <ClipboardList className="h-6 w-6" />
            Gestion des Requêtes
          </h1>
          <p className="text-gray-500 mt-1">
            {allRequests.length} requête{allRequests.length > 1 ? "s" : ""} au
            total
          </p>
        </div>
        <div className="relative w-full sm:w-72">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
          <Input
            placeholder="Rechercher une requête..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
      </div>

      {/* Stats bar */}
      <div className="grid grid-cols-3 gap-4">
        <Card className="border-0 shadow-sm">
          <CardContent className="pt-4 pb-4 text-center">
            <p className="text-2xl font-bold text-yellow-600">{enAttente.length}</p>
            <p className="text-xs text-gray-500">En attente</p>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-sm">
          <CardContent className="pt-4 pb-4 text-center">
            <p className="text-2xl font-bold text-blue-600">{enCours.length}</p>
            <p className="text-xs text-gray-500">En cours</p>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-sm">
          <CardContent className="pt-4 pb-4 text-center">
            <p className="text-2xl font-bold text-green-600">{traites.length}</p>
            <p className="text-xs text-gray-500">Traités</p>
          </CardContent>
        </Card>
      </div>

      {/* Tabs by status */}
      <Tabs defaultValue="en_attente">
        <TabsList>
          <TabsTrigger value="en_attente">
            En attente ({enAttente.length})
          </TabsTrigger>
          <TabsTrigger value="en_cours">
            En cours ({enCours.length})
          </TabsTrigger>
          <TabsTrigger value="traite">Traités ({traites.length})</TabsTrigger>
          <TabsTrigger value="all">Tout ({filtered.length})</TabsTrigger>
        </TabsList>

        <TabsContent value="en_attente" className="space-y-2 mt-4">
          {enAttente.length > 0 ? (
            enAttente.map((r) => <RequestCard key={r.id} request={r} />)
          ) : (
            <p className="text-sm text-gray-400 text-center py-8">
              Aucune requête en attente
            </p>
          )}
        </TabsContent>

        <TabsContent value="en_cours" className="space-y-2 mt-4">
          {enCours.length > 0 ? (
            enCours.map((r) => <RequestCard key={r.id} request={r} />)
          ) : (
            <p className="text-sm text-gray-400 text-center py-8">
              Aucune requête en cours
            </p>
          )}
        </TabsContent>

        <TabsContent value="traite" className="space-y-2 mt-4">
          {traites.length > 0 ? (
            traites.map((r) => <RequestCard key={r.id} request={r} />)
          ) : (
            <p className="text-sm text-gray-400 text-center py-8">
              Aucune requête traitée
            </p>
          )}
        </TabsContent>

        <TabsContent value="all" className="space-y-2 mt-4">
          {filtered.map((r) => (
            <RequestCard key={r.id} request={r} />
          ))}
        </TabsContent>
      </Tabs>

      {/* Detail dialog */}
      <Dialog open={showDetail} onOpenChange={setShowDetail}>
        <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
          {selectedRequest && (
            <>
              <DialogHeader>
                <DialogTitle className="flex items-center gap-2">
                  {statusIcon(selectedRequest.status)}
                  {REQUEST_TYPE_LABELS[selectedRequest.type]}
                </DialogTitle>
              </DialogHeader>
              <div className="space-y-4 pt-2">
                <div className="grid grid-cols-2 gap-3 text-sm">
                  <div>
                    <span className="text-gray-400">N° Requête</span>
                    <p className="font-semibold">{selectedRequest.numero}</p>
                  </div>
                  <div>
                    <span className="text-gray-400">Statut</span>
                    <div className="mt-0.5">
                      <Badge
                        className={statusColor(selectedRequest.status)}
                        variant="secondary"
                      >
                        {REQUEST_STATUS_LABELS[selectedRequest.status]}
                      </Badge>
                    </div>
                  </div>
                  <div>
                    <span className="text-gray-400">Client</span>
                    <p className="font-semibold">{selectedRequest.clientNom}</p>
                  </div>
                  <div>
                    <span className="text-gray-400">Date de soumission</span>
                    <p className="font-semibold">{selectedRequest.createdAt}</p>
                  </div>
                </div>

                {/* Documents joints */}
                {selectedRequest.documents.length > 0 && (
                  <div>
                    <p className="text-sm font-semibold text-gray-700 mb-2">
                      Documents joints par le client
                    </p>
                    <div className="space-y-1">
                      {selectedRequest.documents.map((doc) => (
                        <div
                          key={doc.id}
                          className="flex items-center justify-between p-2 bg-gray-50 rounded-lg text-sm"
                        >
                          <div className="flex items-center gap-2">
                            <FileText className="h-4 w-4 text-gray-400" />
                            <span>{doc.nom}</span>
                          </div>
                          <Button variant="ghost" size="sm">
                            <Download className="h-4 w-4" />
                          </Button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Livrables */}
                <div>
                  <p className="text-sm font-semibold text-gray-700 mb-2">
                    Livrables (documents à remettre au client)
                  </p>
                  {selectedRequest.livrables.length > 0 && (
                    <div className="space-y-1 mb-2">
                      {selectedRequest.livrables.map((doc) => (
                        <div
                          key={doc.id}
                          className="flex items-center justify-between p-2 bg-green-50 rounded-lg text-sm"
                        >
                          <div className="flex items-center gap-2">
                            <FileText className="h-4 w-4 text-green-500" />
                            <span className="text-green-700">{doc.nom}</span>
                          </div>
                          <Button variant="ghost" size="sm">
                            <Download className="h-4 w-4" />
                          </Button>
                        </div>
                      ))}
                    </div>
                  )}
                  <input
                    type="file"
                    ref={fileInputRef}
                    className="hidden"
                    accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"
                    onChange={handleFileSelected}
                  />
                  <div
                    className="border-2 border-dashed border-gray-300 rounded-xl p-4 text-center hover:border-[hsl(222,47%,20%)] hover:bg-blue-50/50 transition cursor-pointer"
                    onClick={handleUploadLivrable}
                  >
                    <Upload className="h-6 w-6 text-gray-400 mx-auto mb-1" />
                    <p className="text-xs font-medium text-gray-600">
                      Cliquez pour téléverser un document
                    </p>
                    <p className="text-xs text-gray-400">
                      Facture, reçu, contrat, attestation, etc.
                    </p>
                  </div>
                </div>

                {/* Actions */}
                <div className="flex gap-2 pt-2">
                  {selectedRequest.status !== "traite" && (
                    <Button
                      onClick={handleMarkAsTreated}
                      className="flex-1 bg-green-600 hover:bg-green-700 text-white"
                    >
                      <CheckCircle className="h-4 w-4 mr-2" />
                      Marquer comme traité
                    </Button>
                  )}
                  <Button
                    variant="outline"
                    className="flex-1"
                    onClick={() => setShowDetail(false)}
                  >
                    Fermer
                  </Button>
                </div>
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { RefreshCw, Upload, ArrowLeft, Send } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { requestsApi } from "@/lib/api";
import { toast } from "sonner";

export default function ChangePage() {
  const router = useRouter();
  const [changement, setChangement] = useState("");
  const [carteGriseUploaded, setCarteGriseUploaded] = useState(false);

  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!changement) {
      toast.error("Veuillez sélectionner le type de changement");
      return;
    }
    if (!carteGriseUploaded) {
      toast.error("Veuillez uploader la nouvelle carte grise");
      return;
    }
    setLoading(true);
    try {
      const typeMap: Record<string, string> = { nom: "changement_nom", immatriculation: "changement_immatriculation" };
      await requestsApi.create(typeMap[changement] || "changement_nom", {});
      toast.success("Votre demande de changement a été soumise.");
      router.push("/client/history");
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors de la soumission");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-lg mx-auto space-y-6">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <RefreshCw className="h-6 w-6 text-orange-600" />
            Demande de Changement
          </h1>
        </div>
      </div>

      <Card className="border-0 shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg">Formulaire de changement</CardTitle>
          <CardDescription>Sélectionnez le type de changement et uploadez la nouvelle carte grise.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-1.5">
            <Label>Type de changement *</Label>
            <Select value={changement} onValueChange={setChangement}>
              <SelectTrigger>
                <SelectValue placeholder="Sélectionnez..." />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="nom">Changement de Nom</SelectItem>
                <SelectItem value="immatriculation">Changement d&apos;Immatriculation</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label>Nouvelle carte grise *</Label>
            <div
              className={`border-2 border-dashed rounded-xl p-6 text-center transition cursor-pointer ${
                carteGriseUploaded
                  ? "border-green-300 bg-green-50"
                  : "border-gray-300 hover:border-[hsl(222,47%,20%)] hover:bg-blue-50/50"
              }`}
              onClick={() => setCarteGriseUploaded(true)}
            >
              <Upload className={`h-8 w-8 mx-auto mb-2 ${carteGriseUploaded ? "text-green-500" : "text-gray-400"}`} />
              {carteGriseUploaded ? (
                <p className="text-sm text-green-700 font-medium">✓ Nouvelle carte grise uploadée</p>
              ) : (
                <>
                  <p className="text-sm font-medium text-gray-600">Cliquez pour uploader la nouvelle carte grise</p>
                  <p className="text-xs text-gray-400 mt-1">PDF, JPG ou PNG (max 5MB)</p>
                </>
              )}
            </div>
          </div>

          <Button
            onClick={handleSubmit}
            className="w-full bg-amber-500 hover:bg-amber-600 text-white"
          >
            <Send className="h-4 w-4 mr-2" />
            Soumettre la demande
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useRef } from "react";
import { useRouter } from "next/navigation";
import { Car, Upload, ArrowLeft, Send } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuthStore } from "@/stores/auth-store";
import { requestsApi, documentsApi } from "@/lib/api";
import { toast } from "sonner";

export default function CotationAutoPage() {
  const router = useRouter();
  const { user } = useAuthStore();
  const [carteGriseUploaded, setCarteGriseUploaded] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [form, setForm] = useState({
    nom: user ? `${user.nom} ${user.prenoms}` : "",
    telephone: user?.telephone || "",
    email: user?.email || "",
    marque: "",
    immatriculation: "",
    genre: "",
    energie: "",
    puissanceFiscale: "",
    placesAssises: "",
    dateMiseCirculation: "",
    usage: "",
    valeurNeuve: "",
    valeurVenale: "",
  });

  const handleCarteGriseUpload = () => {
    fileInputRef.current?.click();
  };

  const handleCarteGriseSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      // VRAI UPLOAD de la carte grise
      const result = await documentsApi.uploadCarteGrise(file);

      setCarteGriseUploaded(true);
      toast.success(`Carte grise "${file.name}" uploadée avec succès (${(result.file_size / 1024).toFixed(1)}KB)`);

    } catch (error: any) {
      toast.error(error.message || "Erreur lors de l'upload de la carte grise");
    }
  };

  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    // Validation: la carte grise doit être uploadée
    if (!carteGriseUploaded) {
      toast.error("Veuillez uploader votre carte grise");
      return;
    }

    if (!form.marque || !form.immatriculation) {
      toast.error("Veuillez renseigner au minimum la marque et l'immatriculation");
      return;
    }
    setLoading(true);
    try {
      await requestsApi.create("cotation_auto", { ...form });
      toast.success("Votre demande de cotation automobile a été envoyée. Vous recevrez un devis sous 24h.");
      router.push("/client/history");
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors de la soumission");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Car className="h-6 w-6 text-blue-600" />
            Cotation Automobile
          </h1>
          <p className="text-gray-500 text-sm mt-0.5">Demandez un devis en quelques clics</p>
        </div>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-xl p-4">
        <p className="text-sm text-blue-800">
          <strong>Cotation rapide :</strong> Uploadez simplement votre carte grise et nous vous
          enverrons un devis personnalisé dans les 24 heures.
        </p>
      </div>

      <Card className="border-0 shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg">Informations du véhicule</CardTitle>
          <CardDescription>Uploadez votre carte grise (obligatoire) puis remplissez les informations.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Input file caché pour la carte grise */}
          <input
            ref={fileInputRef}
            type="file"
            accept=".pdf,.jpg,.jpeg,.png"
            onChange={handleCarteGriseSelected}
            className="hidden"
          />

          <div
            className={`border-2 border-dashed rounded-xl p-6 text-center transition cursor-pointer ${
              carteGriseUploaded
                ? "border-green-300 bg-green-50"
                : "border-gray-300 hover:border-blue-400 hover:bg-blue-50/50"
            }`}
            onClick={handleCarteGriseUpload}
          >
            <Upload className={`h-8 w-8 mx-auto mb-2 ${carteGriseUploaded ? "text-green-500" : "text-gray-400"}`} />
            {carteGriseUploaded ? (
              <p className="text-sm text-green-700 font-medium">✓ Carte grise uploadée avec succès</p>
            ) : (
              <>
                <p className="text-sm font-medium text-gray-600">Cliquez pour uploader la carte grise</p>
                <p className="text-xs text-gray-400 mt-1">PDF, JPG ou PNG (max 5MB)</p>
              </>
            )}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label>Nom & Prénoms</Label>
              <Input value={form.nom} onChange={(e) => setForm({ ...form, nom: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Téléphone</Label>
              <Input value={form.telephone} onChange={(e) => setForm({ ...form, telephone: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Marque / Modèle *</Label>
              <Input value={form.marque} onChange={(e) => setForm({ ...form, marque: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Immatriculation *</Label>
              <Input value={form.immatriculation} onChange={(e) => setForm({ ...form, immatriculation: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Genre</Label>
              <Input value={form.genre} onChange={(e) => setForm({ ...form, genre: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Énergie</Label>
              <Input value={form.energie} onChange={(e) => setForm({ ...form, energie: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Puissance fiscale (CV)</Label>
              <Input value={form.puissanceFiscale} onChange={(e) => setForm({ ...form, puissanceFiscale: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Places assises</Label>
              <Input value={form.placesAssises} onChange={(e) => setForm({ ...form, placesAssises: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Date mise en circulation</Label>
              <Input type="date" value={form.dateMiseCirculation} onChange={(e) => setForm({ ...form, dateMiseCirculation: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Usage</Label>
              <Input value={form.usage} onChange={(e) => setForm({ ...form, usage: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Valeur neuve (FCFA)</Label>
              <Input type="number" value={form.valeurNeuve} onChange={(e) => setForm({ ...form, valeurNeuve: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>Valeur vénale (FCFA)</Label>
              <Input type="number" value={form.valeurVenale} onChange={(e) => setForm({ ...form, valeurVenale: e.target.value })} />
            </div>
          </div>

          <Button onClick={handleSubmit} disabled={loading} className="w-full bg-amber-500 hover:bg-amber-600 text-white">
            <Send className="h-4 w-4 mr-2" /> Demander la cotation
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { FileText, Clock, CheckCircle, AlertCircle, Search } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { useState } from "react";
import { useAuthStore } from "@/stores/auth-store";
import { useClientRequests } from "@/hooks/use-api-data";
import { REQUEST_TYPE_LABELS, REQUEST_STATUS_LABELS } from "@/lib/types";

export default function HistoryPage() {
  const { user } = useAuthStore();
  const { data: requests } = useClientRequests(user?.id || "u1");
  const [search, setSearch] = useState("");

  const filtered = requests.filter(
    (r) =>
      r.numero.toLowerCase().includes(search.toLowerCase()) ||
      REQUEST_TYPE_LABELS[r.type].toLowerCase().includes(search.toLowerCase())
  );

  const statusIcon = (status: string) => {
    switch (status) {
      case "en_attente": return <Clock className="h-4 w-4 text-yellow-500" />;
      case "en_cours": return <AlertCircle className="h-4 w-4 text-blue-500" />;
      case "traite": return <CheckCircle className="h-4 w-4 text-green-500" />;
      default: return <Clock className="h-4 w-4 text-gray-400" />;
    }
  };

  const statusColor = (status: string) => {
    switch (status) {
      case "en_attente": return "bg-yellow-100 text-yellow-800";
      case "en_cours": return "bg-blue-100 text-blue-800";
      case "traite": return "bg-green-100 text-green-800";
      default: return "bg-gray-100 text-gray-800";
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Historique des opérations</h1>
          <p className="text-gray-500 mt-1">Suivez l&apos;évolution de vos requêtes</p>
        </div>
        <div className="relative w-full sm:w-72">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
          <Input
            placeholder="Rechercher une requête..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
      </div>

      <div className="space-y-3">
        {filtered.map((r) => (
          <Card key={r.id} className="border-0 shadow-sm hover:shadow-md transition">
            <CardContent className="p-4">
              <div className="flex items-start justify-between">
                <div className="flex items-start gap-3">
                  <div className="mt-0.5">{statusIcon(r.status)}</div>
                  <div>
                    <div className="flex items-center gap-2 flex-wrap">
                      <h3 className="text-sm font-semibold">{REQUEST_TYPE_LABELS[r.type]}</h3>
                      <Badge className={statusColor(r.status)} variant="secondary">
                        {REQUEST_STATUS_LABELS[r.status]}
                      </Badge>
                    </div>
                    <p className="text-xs text-gray-500 mt-1">
                      {r.numero} • Soumis le {r.createdAt}
