import { toast } from "sonner";

export default function IncorporationPage() {
  const router = useRouter();
  const { user } = useAuthStore();
  const [step, setStep] = useState(1);
  const [carteGriseUploaded, setCarteGriseUploaded] = useState(false);

  const [souscripteur, setSouscripteur] = useState({
    nom: user ? `${user.nom} ${user.prenoms}` : "",
    profession: user?.profession || "",
    adressePostale: "",
    telephone: user?.telephone || "",
  });

  const [vehicule, setVehicule] = useState({
    proprietaire: "",
    immatriculation: "",
    marque: "",
    genre: "",
    usage: "",
    energie: "",
    puissanceFiscale: "",
    placesAssises: "",
    ptac: "",
    pv: "",
    cu: "",
    dateMiseCirculation: "",
    valeurNeuve: "",
    valeurVenale: "",
  });

  const handleCarteGriseUpload = () => {
    setCarteGriseUploaded(true);
    setVehicule({
      ...vehicule,
      proprietaire: user ? `${user.nom} ${user.prenoms}` : "",
      immatriculation: "8888 ZZ 01",
      marque: "Hyundai Tucson",
      genre: "VP",
      usage: "Promenade et affaires",
      energie: "Essence",
      puissanceFiscale: "9",
      placesAssises: "5",
      ptac: "2100",
      pv: "1500",
      cu: "600",
      dateMiseCirculation: "2024-03-10",
    });
    toast.success("Carte grise analysée — Données extraites");
  };

  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      await requestsApi.create("incorporation", { souscripteur, vehicule });
      toast.success("Votre demande d'incorporation a été soumise.");
      router.push("/client/history");
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors de la soumission");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <FileText className="h-6 w-6 text-blue-600" />
