                        <span className="text-green-600">Payé: {formatCurrency(totalPaye)}</span>
                        <span className="text-red-600 font-semibold">Reste: {formatCurrency(solde)}</span>
                      </div>
                    </div>
                    <Button
                      onClick={() => handlePay(e.id)}
