            <Select value={form.contratId} onValueChange={(v) => handleChange("contratId", v)}>
              <SelectTrigger>
                <SelectValue placeholder="Sélectionnez le contrat..." />
              </SelectTrigger>
              <SelectContent>
                {emissions.map((e) => (
                  <SelectItem key={e.id} value={e.id}>
                    {e.risque} — {e.numPolice} ({e.marque !== "-" ? e.marque : e.compagnie})
