      </Card>
    </div>
  );
}

"use client";

import { useState, useRef } from "react";
import { useRouter } from "next/navigation";
import { Car, Upload, ArrowLeft, ArrowRight, Send } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuthStore } from "@/stores/auth-store";
import { requestsApi, documentsApi } from "@/lib/api";
import { toast } from "sonner";

export default function AutomobileSubscriptionPage() {
  const router = useRouter();
  const { user } = useAuthStore();
  const [step, setStep] = useState(1);
  const [carteGriseUploaded, setCarteGriseUploaded] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [souscripteur, setSouscripteur] = useState({
    nom: user ? `${user.nom} ${user.prenoms}` : "",
    profession: user?.profession || "",
    adressePostale: "",
    telephone: user?.telephone || "",
  });

  const [vehicule, setVehicule] = useState({
    proprietaire: user ? `${user.nom} ${user.prenoms}` : "",
    immatriculation: "",
    marque: "",
    genre: "",
    usage: "",
    energie: "",
    puissanceFiscale: "",
    placesAssises: "",
    ptac: "",
    pv: "",
    cu: "",
    dateMiseCirculation: "",
    valeurNeuve: "",
    valeurVenale: "",
  });

  const handleCarteGriseUpload = () => {
    fileInputRef.current?.click();
  };

  const handleCarteGriseSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      // VRAI UPLOAD de la carte grise
      const result = await documentsApi.uploadCarteGrise(file);

      setCarteGriseUploaded(true);

      // Les clients remplissent manuellement les champs
      // Pas de pré-remplissage automatique
      toast.success(`Carte grise "${file.name}" uploadée avec succès (${(result.file_size / 1024).toFixed(1)}KB)`);

    } catch (error: any) {
      toast.error(error.message || "Erreur lors de l'upload de la carte grise");
    }
  };

  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    // Validation: la carte grise doit être uploadée
    if (!carteGriseUploaded) {
      toast.error("Veuillez uploader votre carte grise");
      return;
    }

    setLoading(true);
    try {
      await requestsApi.create("cotation_auto", {
        souscripteur,
        vehicule,
        user_nom: user ? `${user.nom} ${user.prenoms}` : "",
        user_telephone: user?.telephone || "",
        user_email: user?.email || "",
      });
      toast.success("Votre demande de cotation automobile a été soumise.");
      router.push("/client/history");
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Erreur lors de la soumission");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Car className="h-6 w-6 text-blue-600" />
            Souscription Automobile
          </h1>
          <p className="text-gray-500 text-sm mt-0.5">Étape {step} sur 2</p>
        </div>
      </div>

      {/* Progress bar */}
      <div className="flex gap-2">
        <div className={`h-1.5 flex-1 rounded-full ${step >= 1 ? "bg-[hsl(222,47%,20%)]" : "bg-gray-200"}`} />
        <div className={`h-1.5 flex-1 rounded-full ${step >= 2 ? "bg-[hsl(222,47%,20%)]" : "bg-gray-200"}`} />
      </div>

      {/* Step 1: Souscripteur */}
      {step === 1 && (
        <Card className="border-0 shadow-sm">
          <CardHeader>
            <CardTitle className="text-lg">1 — Identification du souscripteur</CardTitle>
            <CardDescription>
              Ces informations sont pré-remplies. Vous pouvez les modifier si nécessaire.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-1.5">
              <Label>Nom & Prénoms *</Label>
              <Input
                value={souscripteur.nom}
                onChange={(e) => setSouscripteur({ ...souscripteur, nom: e.target.value })}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Profession *</Label>
              <Input
                value={souscripteur.profession}
                onChange={(e) => setSouscripteur({ ...souscripteur, profession: e.target.value })}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Adresse postale *</Label>
              <Input
