  const [risque, setRisque] = useState({
    nature: "" as "villa" | "appartement" | "niveau" | "",
    nombreNiveaux: "",
    situationGeographique: "",
    valeurBatiment: "",
    loyerMensuel: "",
    valeurContenu: "",
    nombrePieces: "",
    superficieDeveloppee: "",
