                </label>
              </div>
            </div>
            <div className="flex justify-end pt-2">
              <Button onClick={() => setStep(2)} className="bg-[hsl(222,47%,20%)] hover:bg-[hsl(222,47%,25%)]">
                Suivant <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Step 2: Risque */}
      {step === 2 && (
        <Card className="border-0 shadow-sm">
          <CardHeader>
            <CardTitle className="text-lg">2 — Identification du risque</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-1.5">
              <Label>Nature du risque *</Label>
              <div className="flex gap-4 pt-1 flex-wrap">
                {(["villa", "appartement", "niveau"] as const).map((n) => (
                  <label key={n} className="flex items-center gap-2 cursor-pointer">
                    <input
