import { useAuthStore } from "@/stores/auth-store";

// ── Generic fetch hook — no mock fallback ──

type UseApiOptions = {
  enabled?: boolean;
  deps?: React.DependencyList;
};

function useApi<T>(apiFn: () => Promise<T>, defaultValue: T, options?: UseApiOptions) {
  const { enabled = true, deps = [] } = options || {};
  const [data, setData] = useState<T>(defaultValue);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const memoizedApiFn = useCallback(apiFn, deps);

  const doFetch = useCallback(async () => {
    setLoading(true);
    try {
      const result = await memoizedApiFn();

      // Vérifier si le résultat est un tableau ou un objet valide
      if (result === null || result === undefined) {
        console.warn("[useApi] API returned null/undefined, using default");
        setData(defaultValue);
      } else if (Array.isArray(defaultValue) && !Array.isArray(result)) {
        // Si on attend un tableau mais on reçoit autre chose
        console.warn("[useApi] Expected array but got:", typeof result, result);
        setData(defaultValue);
      } else {
        setData(result);
      }

      setError(null);
    } catch (err) {
      const msg = err instanceof Error ? err.message : "Erreur API";
      console.error("[useApi]", msg);
      setError(msg);
      // En cas d'erreur, garder la valeur par défaut
      setData(defaultValue);
    } finally {
      setLoading(false);
    }
  }, [memoizedApiFn]);

  useEffect(() => {
    if (!enabled) {
      setLoading(false);
      return;
    }
    doFetch();
  }, [enabled, doFetch]);

  return { data, loading, error, refetch: doFetch };
}

// ── Emissions ──

export function useEmissions() {
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  return useApi(() => emissionsApi.list(), [], { enabled: isAuthenticated });
}

export function useClientEmissions(clientId: string) {
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  return useApi(async () => {
    const all = await emissionsApi.list();
    return Array.isArray(all) ? all.filter((e) => e.clientId === clientId) : [];
  }, [], { enabled: isAuthenticated, deps: [clientId, isAuthenticated] });
}

// ── Requests ──

export function useRequests() {
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  return useApi(() => requestsApi.list(), [], { enabled: isAuthenticated });
}

export function useClientRequests(clientId: string) {
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  return useApi(async () => {
    const all = await requestsApi.list();
    return Array.isArray(all) ? all.filter((r) => r.clientId === clientId) : [];
