}

// ── Users ──

export function useUsers(role?: string) {
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  return useApi(() => usersApi.list(role), [], { enabled: isAuthenticated, deps: [role, isAuthenticated] });
}

const emptyPaginatedUsers: PaginatedResponse<User> = {
  results: [],
  count: 0,
  next: null,
  previous: null,
};

export function usePaginatedUsers(params?: UserListParams) {
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  return useApi(() => usersApi.listPaginated(params), emptyPaginatedUsers, {
    enabled: isAuthenticated,
    deps: [params?.role, params?.search, params?.page, params?.pageSize, isAuthenticated],
  });
}

// ── Écheances proches (computed from emissions) ──

export function useEcheancesProches(jours: number = 45) {
  const { data: emissions, loading } = useEmissions();
  const now = new Date();
  const limit = new Date();
  limit.setDate(limit.getDate() + jours);
  const proches = Array.isArray(emissions) ? emissions.filter((e) => {
    const ech = new Date(e.echeance);
    return ech >= now && ech <= limit;
  }) : [];
  return { data: proches, loading };
}

// ── Agent Dashboard Stats (from API) ──

export function useAgentDashboardStats() {
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  const { data: stats, loading } = useApi(() => dashboardApi.stats(), {
    total_contrats: 0,
    contrats_actifs: 0,
    contrats_expires: 0,
    total_primes: 0,
    primes_payees: 0,
    primes_impayees: 0,
    total_clients: 0,
    total_prospects: 0,
    total_agents: 0,
  }, { enabled: isAuthenticated, deps: [isAuthenticated] });

  return {
    stats: {
      totalContrats: stats.total_contrats,
      contratsActifs: stats.contrats_actifs,
      contratsExpires: stats.contrats_expires,
      totalPrimes: stats.total_primes,
      primesPayees: stats.primes_payees,
      primesImpayees: stats.primes_impayees,
      totalClients: stats.total_clients,
      totalProspects: stats.total_prospects,
      totalAgents: stats.total_agents,
    },
    loading,
  };
}

// ── Client Stats (computed from emissions) ──

export function useClientStats(clientId: string) {
  const { data: emissions, loading } = useClientEmissions(clientId);
  const emissionsArray = Array.isArray(emissions) ? emissions : [];

  const stats: CompteStats = {
    primeTotale: emissionsArray.reduce((sum, e) => sum + e.primeTTC, 0),
    primePayee: emissionsArray.reduce(
      (sum, e) => sum + e.paiements.reduce((s, p) => s + p.montantRegle, 0),
      0
    ),
    primeAPayer: 0,
  };
  stats.primeAPayer = stats.primeTotale - stats.primePayee;

  return { stats, emissions: emissionsArray, loading };
}

// ── Audit Logs (admin only) ──

const emptyPaginatedAuditLogs: PaginatedResponse<AuditLogEntry> = {
  results: [],
  count: 0,
  next: null,
  previous: null,
};

export function useAuditLogs(filters?: { userId?: string; action?: string; page?: number; pageSize?: number }) {
  const user = useAuthStore((s) => s.user);
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  const enabled = Boolean(isAuthenticated && user?.role === "admin");
  return useApi(() => auditLogsApi.list(filters), emptyPaginatedAuditLogs, {
    enabled,
    deps: [filters?.userId, filters?.action, filters?.page, filters?.pageSize, enabled],
  });
}

import { useCallback, useRef } from "react";
import { useAuthStore } from "@/stores/auth-store";

interface UseAuthRefreshReturn {
  handleTokenRefresh: () => Promise<boolean>;
  isRefreshing: boolean;
}

export function useAuthRefresh(): UseAuthRefreshReturn {
  const refreshTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const { login, logout, user } = useAuthStore();
  const isRefreshingRef = useRef(false);

  const handleTokenRefresh = useCallback(async (): Promise<boolean> => {
    // Éviter les rafraîchissements multiples
    if (isRefreshingRef.current) {
      return false;
    }

    isRefreshingRef.current = true;

    try {
      // Tenter de rafraîchir le token
      const response = await fetch('/api/auth/token/refresh/', {
        method: 'POST',
        credentials: 'include', // Important pour les cookies
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (response.ok) {
        const data = await response.json();

        // Mettre à jour le user store avec les nouvelles données
        if (data.access) {
          // Le token est rafraîchi, l'utilisateur est toujours authentifié
          return true;
        }
      }

      // Si le rafraîchissement échoue, déconnecter l'utilisateur
      console.warn('Token refresh failed, logging out...');
      logout();
      return false;

    } catch (error) {
      console.error('Token refresh error:', error);

      // En cas d'erreur réseau, essayer de se reconnecter avec les credentials existants
      if (user?.email && user?.nom && user?.prenoms) {
        try {
          const loginSuccess = await login(user.email, '');
          return loginSuccess;
        } catch (loginError) {
          console.error('Auto-login failed:', loginError);
          logout();
          return false;
        }
      }

      logout();
      return false;

    } finally {
      isRefreshingRef.current = false;
    }
  }, [login, logout, user]);

  const scheduleRefresh = useCallback((delay: number) => {
    if (refreshTimeoutRef.current) {
      clearTimeout(refreshTimeoutRef.current);
    }

    refreshTimeoutRef.current = setTimeout(() => {
      handleTokenRefresh();
    }, delay);
  }, [handleTokenRefresh]);

  return {
    handleTokenRefresh,
    isRefreshing: isRefreshingRef.current,
  };
}

"use client";

import { useEffect, useRef, useState, useCallback } from "react";

interface AppNotification {
  id: string;
  title: string;
  message: string;
  type: "info" | "success" | "warning" | "error";
  read_at?: string;
}

interface UseWebSocketReturn {
  notifications: AppNotification[];
  unreadCount: number;
  isConnected: boolean;
  isReconnecting: boolean;
  markAsRead: (id: string) => void;
  markAllAsRead: () => void;
  clearNotifications: () => void;
}

export function useWebSocket(userId?: string): UseWebSocketReturn {
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isReconnecting, setIsReconnecting] = useState(false);

  // 🆕 DÉSACTIVÉ POUR DIAGNOSTIC - Pas de connexion WebSocket
  // Cela éliminera les refreshs en boucle potentiels

  console.log('useWebSocket called with userId:', userId);

  const markAsRead = useCallback((id: string) => {
    setNotifications(prev => 
      prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n)
    );
  }, []);

  const markAllAsRead = useCallback(() => {
    setNotifications(prev => 
      prev.map(n => ({ ...n, read_at: new Date().toISOString() }))
    );
  }, []);

  const clearNotifications = useCallback(() => {
    setNotifications([]);
  }, []);

  const unreadCount = notifications.filter(n => !n.read_at).length;

  return {
    notifications,
    unreadCount,
    isConnected,
    isReconnecting,
    markAsRead,
    markAllAsRead,
    clearNotifications,
  };
}

"use client";

import { useEffect, useRef, useState, useCallback } from "react";

// 🆕 Renommé pour éviter le conflit avec window.Notification
interface AppNotification {
  id: string;
  title: string;
  message: string;
  type: "info" | "success" | "warning" | "error";
  priority: "low" | "medium" | "high" | "urgent";
  created_at: string;
  read_at?: string;
  data?: Record<string, any>;
}

interface UseWebSocketReturn {
  notifications: AppNotification[];
  unreadCount: number;
  isConnected: boolean;
  isReconnecting: boolean;
  markAsRead: (id: string) => void;
  markAllAsRead: () => void;
  clearNotifications: () => void;
}

export function useWebSocket(userId: string): UseWebSocketReturn {
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isReconnecting, setIsReconnecting] = useState(false); // 🆕 État de reconnexion
  const wsRef = useRef<WebSocket | null>(null);
  // 🆕 Compatible navigateur pur
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const reconnectAttempts = useRef(0);
  const maxReconnectAttempts = 5;
  const mountedRef = useRef(true); // 🆕 Éviter les mises à jour après démontage

  // 🆕 Nettoyage idempotent et safe (simplifié sans flag Strict Mode)
  const disconnect = useCallback(() => {
    // Nettoyer le timer de reconnexion
    if (reconnectTimerRef.current) {
      clearTimeout(reconnectTimerRef.current);
      reconnectTimerRef.current = null;
    }

    // Fermer le WebSocket de manière safe
    if (wsRef.current) {
      const ws = wsRef.current;
      if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
        ws.close(1000, "Component unmounting");
      }
      wsRef.current = null;
    }

    setIsConnected(false);
    setIsReconnecting(false);
  }, []);

  // 🆕 Connexion avec dépendance userId (futur-proof)
  const connect = useCallback(() => {
    if (!mountedRef.current) return;

    try {
      // Fermer la connexion existante de manière safe
      if (wsRef.current) {
        const ws = wsRef.current;
        if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
          ws.close(1000, "Reconnecting");
        }
      }

      // Créer nouvelle connexion WebSocket
      const wsUrl = `ws://localhost:8000/ws/notifications/`;
      const ws = new WebSocket(wsUrl);
      wsRef.current = ws;

      ws.onopen = () => {
        if (!mountedRef.current) return;

        console.log('WebSocket connected');
        setIsConnected(true);
        setIsReconnecting(false);
        reconnectAttempts.current = 0;

        // Nettoyer le timer de reconnexion
        if (reconnectTimerRef.current) {
          clearTimeout(reconnectTimerRef.current);
          reconnectTimerRef.current = null;
        }
      };

      ws.onmessage = (event) => {
        if (!mountedRef.current) return;

        try {
          const data = JSON.parse(event.data);

          if (data.type === 'notification') {
            const notification: AppNotification = data.data; // 🆕 Interface renommée

            setNotifications(prev => {
              // Éviter les doublons
              const exists = prev.some(n => n.id === notification.id);
              if (exists) return prev;

              // Ajouter la notification au début
              return [notification, ...prev.slice(0, 49)];
            });

            // 🆕 Utilisation de window.Notification explicite
            if (window.Notification.permission === 'granted' && mountedRef.current) {
              new window.Notification(notification.title, {
                body: notification.message,
                icon: '/favicon.ico',
                tag: notification.id,
              });
            }
          }
        } catch (error) {
          console.error('WebSocket message error:', error);
        }
      };

      ws.onclose = (event) => {
        if (!mountedRef.current) return;

        setIsConnected(false);

        if (event.wasClean) {
          console.log('WebSocket disconnected cleanly');
        } else {
          console.warn(`WebSocket disconnected unexpectedly (code: ${event.code}, reason: ${event.reason || 'Unknown'})`);
        }

        // 🆕 Tentative de reconnexion avec état isReconnecting
        if (reconnectAttempts.current < maxReconnectAttempts && mountedRef.current) {
          reconnectAttempts.current += 1;
          const delay = Math.min(1000 * Math.pow(2, reconnectAttempts.current), 30000);

          setIsReconnecting(true);
          console.log(`Reconnecting in ${delay}ms... (attempt ${reconnectAttempts.current}/${maxReconnectAttempts})`);

          reconnectTimerRef.current = setTimeout(() => {
            if (mountedRef.current) {
              connect();
            }
          }, delay);
        } else {
          console.log('Max reconnect attempts reached');
          setIsReconnecting(false);
        }
      };

      ws.onerror = (error) => {
        if (!mountedRef.current) return;

        // 🆕 Gestion d'erreur simplifiée sans flag Strict Mode
        if (error && error.type !== 'error') {
          console.error('WebSocket error:', error);
        } else {
          console.warn('WebSocket connection error (may be normal in development)');
        }
        setIsConnected(false);
      };

    } catch (error) {
      console.error('WebSocket connection error:', error);
      setIsConnected(false);
    }
  }, [userId]); // 🆕 Dépendance userId pour futur-proof

  // 🆕 useEffect avec dépendances explicites
  useEffect(() => {
    mountedRef.current = true;

    connect();

    return () => {
      mountedRef.current = false;
      disconnect();
    };
  }, [userId, connect, disconnect]);

  const markAsRead = useCallback((id: string) => {
    setNotifications(prev => 
      prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n)
    );

    // TODO: Envoyer le statut lu au backend
    if (mountedRef.current) {
      fetch(`/api/notifications/${id}/read/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      }).catch(error => {
        console.error('Failed to mark notification as read:', error);
      });
    }
  }, []);

  const markAllAsRead = useCallback(() => {
    const unreadIds = notifications.filter(n => !n.read_at).map(n => n.id);

    setNotifications(prev => 
      prev.map(n => ({ ...n, read_at: new Date().toISOString() }))
    );

    // TODO: Envoyer le statut lu au backend pour tous
    if (unreadIds.length > 0 && mountedRef.current) {
      fetch('/api/notifications/mark-all-read/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ notification_ids: unreadIds }),
      }).catch(error => {
        console.error('Failed to mark all notifications as read:', error);
      });
    }
  }, [notifications]);

  const clearNotifications = useCallback(() => {
    setNotifications([]);
  }, []);

  const unreadCount = notifications.filter(n => !n.read_at).length;

  return {
    notifications,
    unreadCount,
    isConnected,
    isReconnecting, // 🆕 Nouvel état exposé
    markAsRead,
    markAllAsRead,
    clearNotifications,
  };
}

"use client";

import { useEffect, useRef, useState, useCallback } from "react";

interface Notification {
  id: string;
  title: string;
  message: string;
  type: "info" | "success" | "warning" | "error";
  priority: "low" | "medium" | "high" | "urgent";
  created_at: string;
  read_at?: string;
  data?: Record<string, any>;
}

interface UseWebSocketReturn {
  notifications: Notification[];
  unreadCount: number;
  isConnected: boolean;
  markAsRead: (id: string) => void;
  markAllAsRead: () => void;
  clearNotifications: () => void;
}

export function useWebSocket(userId: string): UseWebSocketReturn {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<NodeJS.Timeout | null>(null);
  const reconnectAttempts = useRef(0);
  const maxReconnectAttempts = 5;
  const isStrictModeDisconnection = useRef(false); // 🆕 Détecter Strict Mode
  const mountedRef = useRef(true); // 🆕 Éviter les mises à jour après démontage

  // 🆕 Nettoyage idempotent et safe
  const disconnect = useCallback(() => {
    // Nettoyer le timer de reconnexion
    if (reconnectTimerRef.current) {
      clearTimeout(reconnectTimerRef.current);
      reconnectTimerRef.current = null;
    }

    // Fermer le WebSocket de manière safe
    if (wsRef.current) {
      const ws = wsRef.current;
      if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
        isStrictModeDisconnection.current = true; // 🆕 Marquer comme déconnexion Strict Mode
        ws.close(1000, "Component unmounting");
      }
      wsRef.current = null;
    }

    setIsConnected(false);
  }, []);

  // 🆕 Connexion avec protection contre double invocation
  const connect = useCallback(() => {
    if (!mountedRef.current) return; // 🆕 Ne pas connecter si démonté

    try {
      // Fermer la connexion existante de manière safe
      if (wsRef.current) {
        const ws = wsRef.current;
        if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
          ws.close(1000, "Reconnecting");
        }
      }

      // Créer nouvelle connexion WebSocket
      const wsUrl = `ws://localhost:8000/ws/notifications/`;
      const ws = new WebSocket(wsUrl);
      wsRef.current = ws;

      ws.onopen = () => {
        if (!mountedRef.current) return; // 🆕 Ne pas traiter si démonté

        console.log('WebSocket connected');
        setIsConnected(true);
        reconnectAttempts.current = 0;
        isStrictModeDisconnection.current = false; // 🆕 Reset du flag

        // Nettoyer le timer de reconnexion
        if (reconnectTimerRef.current) {
          clearTimeout(reconnectTimerRef.current);
          reconnectTimerRef.current = null;
        }
      };

      ws.onmessage = (event) => {
        if (!mountedRef.current) return; // 🆕 Ne pas traiter si démonté

        try {
          const data = JSON.parse(event.data);

          if (data.type === 'notification') {
            const notification: Notification = data.data;

            setNotifications(prev => {
              // Éviter les doublons
              const exists = prev.some(n => n.id === notification.id);
              if (exists) return prev;

              // Ajouter la notification au début
              return [notification, ...prev.slice(0, 49)];
            });

            // Notification navigateur si permission accordée
            if (Notification.permission === 'granted' && mountedRef.current) {
              new Notification(notification.title, {
                body: notification.message,
                icon: '/favicon.ico',
                tag: notification.id,
              });
            }
          }
        } catch (error) {
          console.error('WebSocket message error:', error);
        }
      };

      ws.onclose = (event) => {
        if (!mountedRef.current) return; // 🆕 Ne pas traiter si démonté

        setIsConnected(false);

        // 🆕 Ignorer les déconnexions Strict Mode
        if (isStrictModeDisconnection.current) {
          console.log('WebSocket disconnected by Strict Mode (normal in development)');
          isStrictModeDisconnection.current = false;
          return;
        }

        if (event.wasClean) {
          console.log('WebSocket disconnected cleanly');
        } else {
          console.warn(`WebSocket disconnected unexpectedly (code: ${event.code}, reason: ${event.reason || 'Unknown'})`);
        }

        // 🆕 Tentative de reconnexion uniquement si ce n'est pas Strict Mode
        if (reconnectAttempts.current < maxReconnectAttempts && mountedRef.current) {
          reconnectAttempts.current += 1;
          const delay = Math.min(1000 * Math.pow(2, reconnectAttempts.current), 30000);

          console.log(`Reconnecting in ${delay}ms... (attempt ${reconnectAttempts.current}/${maxReconnectAttempts})`);

          reconnectTimerRef.current = setTimeout(() => {
            if (mountedRef.current) {
              connect();
            }
          }, delay);
        } else {
          console.log('Max reconnect attempts reached');
        }
      };

      ws.onerror = (error) => {
        if (!mountedRef.current) return; // 🆕 Ne pas traiter si démonté

        // 🆕 Gérer les erreurs Strict Mode différemment
        if (error && error.type !== 'error') {
          console.error('WebSocket error:', error);
        } else {
          console.warn('WebSocket: Connection closed by React Strict Mode (normal in development)');
          isStrictModeDisconnection.current = true; // 🆕 Marquer comme erreur Strict Mode
        }
        setIsConnected(false);
      };

    } catch (error) {
      console.error('WebSocket connection error:', error);
      setIsConnected(false);
    }
  }, []);

  // 🆕 useEffect avec protection contre double invocation
  useEffect(() => {
    mountedRef.current = true; // 🆕 Marquer comme monté

    connect();

    return () => {
      mountedRef.current = false; // 🆕 Marquer comme démonté
      disconnect();
    };
  }, [userId, connect, disconnect]); // 🆕 Dépendances explicites

  const markAsRead = useCallback((id: string) => {
    setNotifications(prev => 
      prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n)
    );

    // TODO: Envoyer le statut lu au backend
    if (mountedRef.current) {
      fetch(`/api/notifications/${id}/read/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      }).catch(error => {
        console.error('Failed to mark notification as read:', error);
      });
    }
  }, []);

  const markAllAsRead = useCallback(() => {
    const unreadIds = notifications.filter(n => !n.read_at).map(n => n.id);

    setNotifications(prev => 
      prev.map(n => ({ ...n, read_at: new Date().toISOString() }))
    );

    // TODO: Envoyer le statut lu au backend pour tous
    if (unreadIds.length > 0 && mountedRef.current) {
      fetch('/api/notifications/mark-all-read/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ notification_ids: unreadIds }),
      }).catch(error => {
        console.error('Failed to mark all notifications as read:', error);
      });
    }
  }, [notifications]);

  const clearNotifications = useCallback(() => {
    setNotifications([]);
  }, []);

  const unreadCount = notifications.filter(n => !n.read_at).length;

  return {
    notifications,
    unreadCount,
    isConnected,
    markAsRead,
    markAllAsRead,
    clearNotifications,
  };
}

"use client";

import { useEffect, useRef, useState, useCallback } from "react";

interface AppNotification {
  id: string;
  title: string;
  message: string;
  type: "info" | "success" | "warning" | "error";
  read_at?: string;
}

interface UseWebSocketReturn {
  notifications: AppNotification[];
  unreadCount: number;
  isConnected: boolean;
  isReconnecting: boolean;
  markAsRead: (id: string) => void;
  markAllAsRead: () => void;
  clearNotifications: () => void;
}

export function useWebSocket(userId?: string): UseWebSocketReturn {
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isReconnecting, setIsReconnecting] = useState(false);

  // 🆕 DÉSACTIVÉ POUR DIAGNOSTIC - Pas de connexion WebSocket
  // Cela éliminera les refreshs en boucle potentiels

  console.log('useWebSocket called with userId:', userId);

  const markAsRead = useCallback((id: string) => {
    setNotifications(prev => 
      prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n)
    );
  }, []);

  const markAllAsRead = useCallback(() => {
    setNotifications(prev => 
      prev.map(n => ({ ...n, read_at: new Date().toISOString() }))
    );
  }, []);

  const clearNotifications = useCallback(() => {
    setNotifications([]);
  }, []);

  const unreadCount = notifications.filter(n => !n.read_at).length;

  return {
    notifications,
    unreadCount,
    isConnected,
    isReconnecting,
    markAsRead,
    markAllAsRead,
    clearNotifications,
  };
}

